前言在Linux内核源码分析进程一篇中，讲解了内核中进程的实现原理，本文从开发角度来审视进程。
进程环境程序的开始// source#include &lt;stdlib.h&gt;#include &lt;stdio.h&gt;static void __attribute__ ((constructor)) before_main(void)&#123;    printf(&quot;Before main...\n&quot;);&#125;int main(void)&#123;    printf(&quot;Main!\n&quot;);    return 0;&#125;// complier$ gcc -v first.c -o first[...]#include &quot;...&quot; search starts here:#include &lt;...&gt; search starts here: /usr/lib/gcc/x86_64-linux-gnu/11/include /usr/local/include /usr/include/x86_64-linux-gnu /usr/includeEnd of search list.[...]COLLECT_GCC_OPTIONS=&#x27;-v&#x27; &#x27;-o&#x27; &#x27;first&#x27; &#x27;-mtune=generic&#x27; &#x27;-march=x86-64&#x27; as -v --64 -o /tmp/cckaqfwB.o /tmp/cc6KuP5q.sGNU assembler version 2.38 (x86_64-linux-gnu) using BFD version (GNU Binutils for Ubuntu) 2.38COMPILER_PATH=/usr/lib/gcc/x86_64-linux-gnu/11/:/usr/lib/gcc/x86_64-linux-gnu/11/:/usr/lib/gcc/x86_64-linux-gnu/:/usr/lib/gcc/x86_64-linux-gnu/11/:/usr/lib/gcc/x86_64-linux-gnu/LIBRARY_PATH=/usr/lib/gcc/x86_64-linux-gnu/11/:/usr/lib/gcc/x86_64-linux-gnu/11/../../../x86_64-linux-gnu/:/usr/lib/gcc/x86_64-linux-gnu/11/../../../../lib/:/lib/x86_64-linux-gnu/:/lib/../lib/:/usr/lib/x86_64-linux-gnu/:/usr/lib/../lib/:/usr/lib/gcc/x86_64-linux-gnu/11/../../../:/lib/:/usr/lib/COLLECT_GCC_OPTIONS=&#x27;-v&#x27; &#x27;-o&#x27; &#x27;first&#x27; &#x27;-mtune=generic&#x27; &#x27;-march=x86-64&#x27; &#x27;-dumpdir&#x27; &#x27;first.&#x27; /usr/lib/gcc/x86_64-linux-gnu/11/collect2 -plugin /usr/lib/gcc/x86_64-linux-gnu/11/liblto_plugin.so -plugin-opt=/usr/lib/gcc/x86_64-linux-gnu/11/lto-wrapper -plugin-opt=-fresolution=/tmp/ccL3y8nT.res -plugin-opt=-pass-through=-lgcc -plugin-opt=-pass-through=-lgcc_s -plugin-opt=-pass-through=-lc -plugin-opt=-pass-through=-lgcc -plugin-opt=-pass-through=-lgcc_s --build-id --eh-frame-hdr -m elf_x86_64 --hash-style=gnu --as-needed -dynamic-linker /lib64/ld-linux-x86-64.so.2 -pie -z now -z relro -o first /usr/lib/gcc/x86_64-linux-gnu/11/../../../x86_64-linux-gnu/Scrt1.o /usr/lib/gcc/x86_64-linux-gnu/11/../../../x86_64-linux-gnu/crti.o /usr/lib/gcc/x86_64-linux-gnu/11/crtbeginS.o -L/usr/lib/gcc/x86_64-linux-gnu/11 -L/usr/lib/gcc/x86_64-linux-gnu/11/../../../x86_64-linux-gnu -L/usr/lib/gcc/x86_64-linux-gnu/11/../../../../lib -L/lib/x86_64-linux-gnu -L/lib/../lib -L/usr/lib/x86_64-linux-gnu -L/usr/lib/../lib -L/usr/lib/gcc/x86_64-linux-gnu/11/../../.. /tmp/cckaqfwB.o -lgcc --push-state --as-needed -lgcc_s --pop-state -lc -lgcc --push-state --as-needed -lgcc_s --pop-state /usr/lib/gcc/x86_64-linux-gnu/11/crtendS.o /usr/lib/gcc/x86_64-linux-gnu/11/../../../x86_64-linux-gnu/crtn.oCOLLECT_GCC_OPTIONS=&#x27;-v&#x27; &#x27;-o&#x27; &#x27;first&#x27; &#x27;-mtune=generic&#x27; &#x27;-march=x86-64&#x27; &#x27;-dumpdir&#x27; &#x27;first.&#x27;// outputBefore main...Main!

在链接生成最后的可执行文件时，有大量的C库二进制文件参与进来，如crt1.o、crti.o等。可见最终的可执行文件，除了我们编写的这个简单的C代码以外，还有大量的C库文件参与了链接，并包含在最终的可执行文件中。这个“组装”的过程，是由链接器ld的链接脚本来决定的。在没有指定链接脚本的情况下，会使用ld的默认脚本，可以通过ld–verbose来查看，
❯ ld -verbose[...]// 这里定义了输出的文件格式、目标机器的类型，以及重要的信息和程序的入口ENTRY（_start）​。OUTPUT_FORMAT(&quot;elf64-x86-64&quot;, &quot;elf64-x86-64&quot;,	      &quot;elf64-x86-64&quot;)OUTPUT_ARCH(i386:x86-64)ENTRY(_start)SEARCH_DIR(&quot;=/usr/local/lib/x86_64-linux-gnu&quot;); SEARCH_DIR(&quot;=/lib/x86_64-linux-gnu&quot;); SEARCH_DIR(&quot;=/usr/lib/x86_64-linux-gnu&quot;); SEARCH_DIR(&quot;=/usr/lib/x86_64-linux-gnu64&quot;); SEARCH_DIR(&quot;=/usr/local/lib64&quot;); SEARCH_DIR(&quot;=/lib64&quot;); SEARCH_DIR(&quot;=/usr/lib64&quot;); SEARCH_DIR(&quot;=/usr/local/lib&quot;); SEARCH_DIR(&quot;=/lib&quot;); SEARCH_DIR(&quot;=/usr/lib&quot;); SEARCH_DIR(&quot;=/usr/x86_64-linux-gnu/lib64&quot;); SEARCH_DIR(&quot;=/usr/x86_64-linux-gnu/lib&quot;);SECTIONS&#123;  [...]  /*  * 这里定义了.ctors section，而我们的例子中before_main函数使用的gcc扩展属性__attribute__（​（constructor）​）  * 就是将函数对应的指令归属于.ctors section中。  */  .ctors          :  &#123;    /* gcc uses crtbegin.o to find the start of       the constructors, so we make sure it is       first.  Because this is a wildcard, it       doesn&#x27;t matter if the user does not       actually link against crtbegin.o; the       linker won&#x27;t look for a file to match a       wildcard.  The wildcard also means that it       doesn&#x27;t matter which directory crtbegin.o       is in.  */    KEEP (*crtbegin.o(.ctors))    KEEP (*crtbegin?.o(.ctors))    /* We don&#x27;t want to include the .ctor section from       the crtend.o file until after the sorted ctors.       The .ctor section from the crtend file contains the       end of ctors marker and it must be last */    KEEP (*(EXCLUDE_FILE (*crtend.o *crtend?.o ) .ctors))    KEEP (*(SORT(.ctors.*)))    KEEP (*(.ctors))  &#125;  /*  * 这里定义了.dtors section，是main函数结束调用的代码。  */  .dtors          :  &#123;    KEEP (*crtbegin.o(.dtors))    KEEP (*crtbegin?.o(.dtors))    KEEP (*(EXCLUDE_FILE (*crtend.o *crtend?.o ) .dtors))    KEEP (*(SORT(.dtors.*)))    KEEP (*(.dtors))  &#125;  [...]&#125;

下面我们来追溯一下Linux可执行程序完整的启动过程。前面的链接脚本明确了入口为_start。在32位的x86平台中，_start位于sysdeps/i386/start.S中。
    .text    .globl _start    .type _start,@function_start:    /* Clear the frame pointer.  The ABI suggests this be done, to mark       the outermost frame obviously.  */    xorl %ebp, %ebp    /* Extract the arguments as encoded on the stack and set up       the arguments for `main&#x27;: argc, argv.  envp will be determined       later in __libc_start_main.  */    popl %esi       /* Pop the argument count.  */    movl %esp, %ecx     /* argv starts just at the current stack top.*/    /* Before pushing the arguments align the stack to a 16-byte    (SSE needs 16-byte alignment) boundary to avoid penalties from    misaligned accesses.  Thanks to Edward Seidl &lt;seidl@janed.com&gt;    for pointing this out.  */    andl $0xfffffff0, %esp    pushl %eax      /* Push garbage because we allocate                   28 more bytes.  */    /* Provide the highest stack address to the user code (for stacks       which grow downwards).  */    pushl %esp    pushl %edx      /* Push address of the shared library                   termination function.  */    /* Push address of our own entry points to .fini and .init.  */    pushl $__libc_csu_fini    pushl $__libc_csu_init    pushl %ecx      /* Push second argument: argv.  */    pushl %esi      /* Push first argument: argc.  */    pushl $BP_SYM (main)    /* Call the user&#x27;s main function, and exit with its value.       But let the libc call main.    */    call BP_SYM (__libc_start_main)

上面列出的虽然是汇编代码，但是每一行都有清楚的注释，这段代码主要是为程序的运行创建好运行环境，其中需要注意的是，__libc_csu_fini和__libc_csu_init都被作为参数传给了__libc_start_main。从这两个函数的名字上可以推测它们是用来处理退出和初始化阶段的函数，那么.ctors section中的函数很可能就是由__libc_csu_init来调用的。我们先来关注__libc_csu_init是在何时被调用的，然后再分析其实现。上面的汇编代码将这两个函数作为参数传递给了__libc_start_main，然后又调用了generic_start_main函数。这个函数初始化了C库所需要的环境，如环境变量、函数栈、多线程环境等，最后调用main函数——进入普通应用程序的真正入口。而在此之前，以下代码先被执行：
/* Register the destructor of the program, if any.  */if (fini)    __cxa_atexit ((void (*) (void *)) fini, NULL, NULL);if (init)    (*init) (argc, argv, __environ MAIN_AUXVEC_PARAM);

init即为__libc_csu_init，上面的代码保证了__libc_csu_init在main之前被调用。.ctors的函数调用流程：__libc_csu_init-&gt;_init-&gt;__libc_global_ctors。
void__libc_global_ctors (void)&#123;/* Call constructor functions.  */    run_hooks (__CTOR_LIST__);&#125;static inline voidrun_hooks (void (*const list[]) (void))&#123;    while (*++list)        (**list) ();&#125;static void (*const __CTOR_LIST__[1]) (void)  __attribute__ ((used, section (&quot;.ctors&quot;)))  = &#123; (void (*) (void)) -1 &#125;;

__CTOR_LIST__是一个函数指针数组，数组的大小为1。该数组使用gcc的扩展属性，使__CTOR_LIST__位于.ctors section中。因此，在上面的代码中，__libc_global_ctors将__CTOR_LIST__传递给了run_hooks，实际上就是将.ctors section的起始地址传递给了run_hooks。而__CTOR_LIST__位于.ctors的第一个位置，其本身并不是一个真正的.ctors属性函数，因此run_hooks的while（*++list）先执行自增操作，即跳过了__CTOR_LIST__。
可以通过 r2 反汇编查看二进制的可执行程序来验证：
080483e4 &lt;before_main&gt;:80483e4:       55                      push   %ebp80483e5:       89 e5                   mov    %esp,%ebp80483e7:       83 ec 18                sub    $0x18,%esp80483ea:       c7 04 24 e0 84 04 08    movl   $0x80484e0,(%esp)80483f1:       e8 22 ff ff ff          call   8048318 &lt;puts@plt&gt;80483f6:       c9                      leave80483f7:       c3                      ret

可以看到，函数before_main的地址为0x080483e4。然后使用objdump来查看.ctors section：
objdump -s -j .ctors a.outa.out:     file format elf32-i386Contents of section .ctors:8049f08 ffffffff e4830408 00000000           ……

可以看到，.ctors section的第一个元素即上文中的__CTOR_LIST__，第二个元素为before_main——由于x86是小端CPU，因此0xe4830408实际上表示的地址值为0x080483e4。
需要注意的是，在新版本的gcc中，.ctors属性的函数并不会位于.ctors section中，而是被gcc合并到了.init_array section中，.dtors section也被合并到了.fini_array section中。下面来看一下这种情况下的objdump输出：
# 可以看到，在.ctors section中，没有任何有效的.ctors函数，[fgao@fgao chapter3]#objdump -s -j .ctors a.outa.out:     file format elf32-i386Contents of section .ctors:8049600 ffffffff 00000000# 保存在.init_array section中的函数调用机制与之前分析的.ctors section机制类似的。[fgao@fgao chapter3]#objdump -s -j .init_array a.outa.out:     file format elf32-i386Contents of section .init_array:80495fc b4830408

关于 exit在刚刚学习C语言的时候，我们就被告知分配内存以后，如果不使用free来释放内存，就会造成内存的泄漏。同样，打开文件以后，如果忘记close也会造成资源的泄漏。那么，在进程退出以后，这些资源是否真的泄漏了呢？
当进程正常退出时，会调用C库的exit；而当进程崩溃或被kill掉时，C库的exit则不会被调用，只会执行内核退出进程的操作。
首先，我们来分析C库的退出函数exit，代码如下：
voidexit (int status)&#123;  __run_exit_handlers (status, &amp;__exit_funcs, true);&#125;

C库的exit主要用来执行所有注册的退出函数，比如使用atexit或on_exit注册的函数。执行完注册的退出函数后，__run_exit_handlers会调用_exit，代码如下：
void_exit (status)     int status;&#123;  while (1)    &#123;#ifdef __NR_exit_group      INLINE_SYSCALL (exit_group, 1, status);#endif      INLINE_SYSCALL (exit, 1, status);#ifdef ABORT_INSTRUCTION      ABORT_INSTRUCTION;#endif    &#125;&#125;

上面的代码很简单，当平台有exit_group时，就调用exit_group，否则就调用exit。从Linux内核2.5.35版本以后，为了支持线程，就有了exit_group。这个系统调用不仅仅是用于退出当前线程，还会让所有线程组的线程全部退出。下面来看看系统调用exit_group的实现：
SYSCALL_DEFINE1(exit_group, int, error_code)&#123;    /* do_group_exit做真正的工作 */    do_group_exit((error_code &amp; 0xff) &lt;&lt; 8);    /* NOTREACHED */    return 0;&#125;NORET_TYPE voiddo_group_exit(int exit_code)&#123;    struct signal_struct *sig = current-&gt;signal;    BUG_ON(exit_code &amp; 0x80); /* core dumps don&#x27;t get here */    /* 检查该线程组是否正在退出，如果条件为真，则不需要设置线程组退出的条件，直接执行本线程task退出流程do_exit即可 */    if (signal_group_exit(sig))        exit_code = sig-&gt;group_exit_code;    else if (!thread_group_empty(current)) &#123; /* 线程组不为空 */        struct sighand_struct *const sighand = current-&gt;sighand;        spin_lock_irq(&amp;sighand-&gt;siglock);        /* 标准的双重条件检查机制。因为第一次检查signal_group_exit时为假，        *  但是另外一个线程已经拿到锁，并设置了状态。当拿到锁的时候，需要再次检查        */        if (signal_group_exit(sig)) &#123;            /* Another thread got here before we took the lock.  */            exit_code = sig-&gt;group_exit_code;        &#125;        else &#123;            /* 设置线程组的退出值和退出状态 */            sig-&gt;group_exit_code = exit_code;            sig-&gt;flags = SIGNAL_GROUP_EXIT;            /* 使用SIGKILL“干掉”线程组的其他线程 */            zap_other_threads(current);        &#125;        spin_unlock_irq(&amp;sighand-&gt;siglock);    &#125;    /* 真正的退出动作，退出当前线程task */    do_exit(exit_code);    /* NOTREACHED */&#125;

下面来看看do_exit的实现：
NORET_TYPE void do_exit(long code)&#123;    struct task_struct *tsk = current;    int group_dead;    profile_task_exit(tsk);    WARN_ON(blk_needs_flush_plug(tsk));    /* 中断上下文不能使用退出，因为没有进程上下文 */    if (unlikely(in_interrupt()))        panic(&quot;Aiee, killing interrupt handler!&quot;);    /* pid为0，即内核的idle进程。这个task也是不应该退出的 */    if (unlikely(!tsk-&gt;pid))        panic(&quot;Attempted to kill the idle task!&quot;);    /*     * If do_exit is called because this processes oopsed, it&#x27;s possible     * that get_fs() was left as KERNEL_DS, so reset it to USER_DS before     * continuing. Amongst other possible reasons, this is to prevent     * mm_release()-&gt;clear_child_tid() from writing to a user-controlled     * kernel address.     */    set_fs(USER_DS);    /* 如果task正在被跟踪如gdb，则发送ptrace事件 */    ptrace_event(PTRACE_EVENT_EXIT, code);    validate_creds_for_do_exit(tsk);    /*     * We&#x27;re taking recursive faults here in do_exit. Safest is to just     * leave this task alone and wait for reboot.     */    /* 当task退出的时候，会被设置上PF_EXITING标志。如果发现此时flags已经设置了该标志，则说明发生了错误。此时就要按照注释所说的，最安全的方法是什么都不做，通知并等待重启 */    if (unlikely(tsk-&gt;flags &amp; PF_EXITING)) &#123;        printk(KERN_ALERT            &quot;Fixing recursive fault but reboot is needed!\n&quot;);        /*         * We can do this unlocked here. The futex code uses         * this flag just to verify whether the pi state         * cleanup has been done or not. In the worst case it         * loops once more. We pretend that the cleanup was         * done as there is no way to return. Either the         * OWNER_DIED bit is set by now or we push the blocked         * task into the wait for ever nirwana as well.         */        tsk-&gt;flags |= PF_EXITPIDONE;        /* 将当前task设置为不可中断的状态，然后放弃CPU。 */        set_current_state(TASK_UNINTERRUPTIBLE);        schedule();    &#125;    /*如果当前task是中断线程，即每个CPU中断由一个线程来处理，则设置对应的中断停止来唤醒本线程。    * 这是一个编译选项，默认情况下是关闭的。    */    exit_irq_thread();    /* 给task设置退出标志PF_EXITING */    exit_signals(tsk);  /* sets PF_EXITING */    /*     * tsk-&gt;flags are checked in the futex code to protect against     * an exiting task cleaning up the robust pi futexes.     */    smp_mb();    raw_spin_unlock_wait(&amp;tsk-&gt;pi_lock);    if (unlikely(in_atomic()))        printk(KERN_INFO &quot;note: %s[%d] exited with preempt_count %d\n&quot;,                current-&gt;comm, task_pid_nr(current),                preempt_count());    acct_update_integrals(tsk);    /* sync mm&#x27;s RSS info before statistics gathering */    /* 该task有自己的内存空间 */    if (tsk-&gt;mm)        sync_mm_rss(tsk, tsk-&gt;mm); //更新内存统计计数    /* 判断整个线程组是否都已经退出。*/    group_dead = atomic_dec_and_test(&amp;tsk-&gt;signal-&gt;live);    if (group_dead) &#123;        /* 取消高精度定时器 */        hrtimer_cancel(&amp;tsk-&gt;signal-&gt;real_timer);        /* 删除task的内部定时器，对应系统调用getitimer和setitimer */        exit_itimers(tsk-&gt;signal);        if (tsk-&gt;mm)            setmax_mm_hiwater_rss(&amp;tsk-&gt;signal-&gt;maxrss, tsk-&gt;mm);    &#125;    acct_collect(code, group_dead);    /* 如果整个线程组都已经退出，则释放授权资源 */    if (group_dead)        tty_audit_exit();    if (unlikely(tsk-&gt;audit_context))        audit_free(tsk);    /* 设置task的退出值 */    tsk-&gt;exit_code = code;    /* 释放任务统计资源 */    taskstats_exit(tsk, group_dead);    /*    释放task的内存空间。task使用的所有内存页都由内核来维护。对于用户程序，如果忘记释放申请的内存，则只会造成用户程序无法再使用该内存，因为内核认为该内存仍然在被用户程序使用。当task退出时，内核会负责释放所有的内存地址。因此当进程退出时，所有申请的内存都会被释放，不会有任何的内存泄漏。    */    exit_mm(tsk);    if (group_dead)        acct_process();    trace_sched_process_exit(tsk);    /*    检查是否释放了semphore资源，如没有释放则执行semphore的undo操作。这点用于保证在进程意外退出时，能恢复semphore的正确状态，也可以用于预防错误的程序逻辑所导致的semphore释放操作遗漏。    */    exit_sem(tsk);    /* 释放共享内存 */    exit_shm(tsk);    /*    如果文件资源没有被共享，则释放所有的文件资源。即使用户程序有文件泄漏也不必担心，一旦task退出，文件资源都会得到正确的释放—因为内核维护了所有的、打开的文件。    */    exit_files(tsk);    /* 释放task的文件系统资源，如当前目录、根目录等*/    exit_fs(tsk);    check_stack_usage();    /* 释放task资源，如TSS段等 */    exit_thread();    /*     * Flush inherited counters to the parent - before the parent     * gets woken up by child-exit notifications.         *     * because of cgroup mode, must be called before cgroup_exit()     */    perf_event_exit_task(tsk);    /* 从控制组退出，并释放相关资源 */    cgroup_exit(tsk, 1);    /* 如果线程组都已经退出，则断开控制终端即tty */    if (group_dead)        disassociate_ctty(1);    /* 后面仍然是一些task退出的清理工作，因与本节关系不大，所以在此不再一一列出了 */    ……&#125;

从exit的源码可以得知，即使应用程序在应用层有内存泄漏或文件句柄泄漏也不必担心，当进程退出时，内核的exit_group调用将会默默地在后面做着清理工作，释放所有内存，关闭所有文件，以及其他资源——当然，前提条件是这些资源是该进程独享的。
关于 atexit#include &lt;stdlib.h&gt;#include &lt;stdio.h&gt;static void callback1(void)&#123;    printf(&quot;callback1\n&quot;);&#125;static void callback2(void)&#123;    printf(&quot;callback2\n&quot;);&#125;static void callback3(void)&#123;    printf(&quot;callback3\n&quot;);&#125;int main(void)&#123;    atexit(callback1);    atexit(callback2);    atexit(callback3);    printf(&quot;main exit\n&quot;);    return 0;&#125;// outputmain exitcallback3callback2callback1

从上面的代码输出可以看出，我们顺序地注册callback1、callback2和callback3，当进程退出时，其调用顺序为callback3、callback2和callback1。
使用atexit注册的退出函数是在进程正常退出时，才会被调用。这里的正常退出是指，使用exit退出或使用main中最后的return语句退出。若是因为收到信号而导致程序退出，atexit注册的退出函数则不会被调用。下面我们通过一个测试程序来验证这一观点：
#include &lt;stdlib.h&gt;#include &lt;stdio.h&gt;#include &lt;unistd.h&gt;static void callback1(void)&#123;    printf(&quot;callback1\n&quot;);&#125;int main(void)&#123;    atexit(callback1);    while (1) &#123;        sleep(1);    &#125;    printf(&quot;main exit\n&quot;);    return 0;&#125;// terminal&gt;                                | &gt; ./atexit_signal;&gt; killall atexit_signal  		 |  &gt;    							 |    Terminated

我们会发现atexit注册的退出函数并没有被调用，下面我们来看一下其在 glibc 中的源码：
int#ifndef atexitattribute_hidden#endifatexit (void (*func) (void))&#123;    /* __dso_handle是动态共享对象的句柄，此处可以略过 */    return __cxa_atexit ((void (*) (void *)) func, NULL,             &amp;__dso_handle == NULL ? NULL : __dso_handle);&#125;int__cxa_atexit (void (*func) (void *), void *arg, void *d)&#123;    /* __exit_funcs为退出函数的链表 */    return __internal_atexit (func, arg, d, &amp;__exit_funcs);&#125;intattribute_hidden__internal_atexit (void (*func) (void *), void *arg, void *d,          struct exit_function_list **listp)&#123;    /* 在退出函数链表中，得到一个新的节点 */  struct exit_function *new = __new_exitfn (listp);  if (new == NULL)    return -1;#ifdef PTR_MANGLE  PTR_MANGLE (func);#endif  /* 初始化这个节点，将函数及其参数赋给这个节点 */  new-&gt;func.cxa.fn = (void (*) (void *, int)) func;  new-&gt;func.cxa.arg = arg;  new-&gt;func.cxa.dso_handle = d;  atomic_write_barrier ();  new-&gt;flavor = ef_cxa;  return 0;&#125;

上面的代码揭示了atexit是如何把函数注册到退出函数链表中的。那么，这些函数又是何时被调用的呢？回忆atexit的介绍，退出注册函数只有在程序正常退出或调用exit时才会被执行。程序正常退出时，系统就会调用exit。因此，问题的关键就在于exit函数了：
voidexit (int status)&#123;  __run_exit_handlers (status, &amp;__exit_funcs, true);&#125;

在这里，__run_exit_handlers会遍历__exit_funcs，一一调用注册的退出函数，在此就不再罗列其代码了。从atexit的实现机制上进行分析，我们可以得出atexit的实现是依赖于C库的代码的。当进程收到信号时，如果没有注册对应的信号处理函数，那么内核就会执行信号的默认动作，一般是直接终止进程。这时，进程的退出完全由内核来完成，自然不会调用到C库的exit函数，也就无法调用注册的退出函数了。
环境变量Linux环境下，程序在启动的时候都会从shell环境下继承当前的环境变量，如PATH、HOME、TZ等。我们也可以通过C库的接口来增加、修改或删除当前进程的环境变量，putenv用于增加或修改当前的环境变量。string的格式为“名字&#x3D;值”。如果当前环境变量没有该名称的环境变量，则增加这个新的环境变量；如果已经存在，则使用新值。看似功能很简单，但实际上使用这个接口时，却很容易犯错。请看下面的代码：
#include &lt;stdlib.h&gt;#include &lt;stdio.h&gt;static void set_env_string(void)&#123;    char test_env[] = &quot;test_env=test&quot;;    if (0 != putenv(test_env)) &#123;        printf(&quot;fail to putenv\n&quot;);    &#125;    printf(&quot;1. The test_evn string is %s\n&quot;, getenv(&quot;test_env&quot;));&#125;static void show_env_string(void)&#123;    printf(&quot;2. The test_env string is %s\n&quot;, getenv(&quot;test_env&quot;));&#125;int main()&#123;    set_env_string();    show_env_string();    return 0;&#125;// output1. The test_evn string is test2. The test_env string is (null)

使用putenv添加环境变量时，参数直接被当作环境变量的一部分了。对于本例而言，set_env_string中的test_env数组直接被环境变量引用了。而test_env是一个局部变量，在执行set_env_string的时候，test_env已经不存在了，对应栈上的内存会在后面的函数调用中使用，并存入其他值。因此，在进入show_env_string的时候，就无法得到正确的值了。

笔者曾经修改过一个因为putenv引起的bug，当时也是费了很大一番力气才找到根本原因，所以颇为气愤当时的开发人员为什么在使用putenv的时候，不认真阅读该接口的说明。Martin Golding曾说过一句话“编程的时候，要总是想着那个维护你代码的人会是一个知道你住在哪儿的、有暴力倾向的精神病患者”。

如果非要用putenv来设置环境变量，就必须要保证参数是一个长期存在的内容。因此，只能选择全局变量、常量或动态内存等。为了避免犯错，我们应该尽量使用另外一个接口setenv，代码如下：
#include &lt;stdlib.h&gt;/* @name：要加入的环境变量名称。*  @value：该环境变量的值。*  @overwrite：用于指示是否覆盖已存在的重名环境变量。0不覆盖，非0则覆盖。*/int setenv(const char *name, const char *value, int overwrite);

#include &lt;stdlib.h&gt;#include &lt;stdio.h&gt;static void set_env_string(void)&#123;    setenv(&quot;test_env&quot;, &quot;test&quot;, 1);    printf(&quot;1. The test_evn string is %s\n&quot;, getenv(&quot;test_env&quot;));&#125;static void show_env_string(void)&#123;    printf(&quot;2. The test_env string is %s\n&quot;, getenv(&quot;test_env&quot;));&#125;int main()&#123;    set_env_string();    show_env_string();    return 0;&#125;// output1. The test_evn string is test2. The test_env string is test

动态库编译生成和使用动态库$ cat 4_5_2_dlib.c#include &lt;stdlib.h&gt;#include &lt;stdio.h&gt;void dynamic_lib_call(void)&#123;    printf(&quot;dynamic lib call\n&quot;);&#125;$ gcc -Wall -shared 4_5_2_dlib.c -o libdlib.so$ cat 4_5_2_main.c#include &lt;stdlib.h&gt;#include &lt;stdio.h&gt;extern void dynamic_lib_call(void);int main(void)&#123;    dynamic_lib_call();    return 0;&#125;$ gcc -Wall 4_5_2_main.c -o test_dlib -L ./-ldlib$ ./test_dlib./test_dlib: error while loading shared libraries: libdlib.so: cannot open shared object file: No such file or directory$ ldd test_dlib        linux-gate.so.1 =&gt;  (0xb7785000)        libdlib.so =&gt; not found        libc.so.6 =&gt; /lib/i386-linux-gnu/libc.so.6 (0xb75ce000)        /lib/ld-linux.so.2 (0xb7786000)

显示无法找到libdlib.so。原因在于-L只是在gcc编译的过程中指示库的位置，而在程序运行的时候，动态库的加载路径默认为/lib和/usr/lib。在Linux环境下，还可以通过/etc/ld.so.conf配置文件和环境变量LD_LIBRARY_PATH指示额外的动态库路径，或者使用patch_elf修改动态库路径。为简单起见，我们在这里将libdlib.so复制到/usr/lib目录下，再运行test_dlib试试：
$ cp /home/fgao/works/my_git_codes/my_books/understanding_apue/sample_codes/chapter3/libdlib.so .$ ./test_dlibdynamic lib call

上面的例子中，动态库是由系统自动加载的，所以需要将动态库放在指定的目录下。然而，C库还提供了dlopen等接口来支持手工加载动态库的功能，代码如下：
#include &lt;stdlib.h&gt;#include &lt;stdio.h&gt;#include &lt;dlfcn.h&gt;int main()&#123;    void *dlib = dlopen(&quot;./libdlib.so&quot;, RTLD_NOW);    if (!dlib) &#123;        printf(&quot;dlopen failed\n&quot;);        return -1;    &#125;    void (*dfunc) (void) = dlsym(dlib, &quot;dynamic_lib_call&quot;);    if (!dfunc) &#123;        printf(&quot;dlsym failed\n&quot;);        return -1;    &#125;    dfunc();    dlclose(dlib);    return 0;&#125;$ gcc -Wall 4_5_2_main_mlib.c -ldl -o test_mlib$ ./test_dlibdynamic lib call 

#include &lt;dlfcn.h&gt;// 以指定模式打开指定的动态连接库文件，并返回一个句柄给调用进程。// flag中必须设置以下的mode：// RTLD_LAZY 暂缓决定，等有需要时再解出符号 // RTLD_NOW 立即决定，返回前解除所有未决定的符号。void *dlopen(const char *filename, int flag);// 当动态链接库操作函数执行失败时，可以返回出错信息，返回值为NULL时，表示没有错误信息。char *dlerror(void);// handle是由dlopen打开动态链接库后返回的指针，symbol就是要求获取的函数的名称，函数返回值是void*,指向函数的地址，供调用使用。void *dlsym(void *handle, const char *symbol);// 将该.so的引用计数减一，当引用计数为0时，将它从系统中卸载。int dlclose(void *handle);

动态升级动态库的一个重要优点就是，可执行程序并不包含动态库中的任何指令，而是在运行时加载动态库并完成调用。这就给我们提供了升级动态库的机会。只要保证接口不变，使用新版本的动态库替换原来的动态库，就完成了动态库的升级。
更新完库文件以后启动的可执行程序都会使用新的动态库。这样的更新方法只能够影响更新以后启动的程序，对于正在运行的程序则无法产生效果，因为程序在运行时，旧的动态库文件已经加载到内存中了。我们只能更新位于磁盘上的动态库的物理文件，而不能影响已经位于内存中的库了。
对于服务程序来说，重启会付出很大的代价并带来糟糕的用户体验。但可以使用前面介绍的手工加载动态库的方法。下面的伪代码将给出一个比较简单的解决方案。
// (1) 使用一个结构体来管理动态库的接口：struct dlib_manager &#123;    void *dlib_handle; //保存动态库的句柄    int (service_func) (void *);    int (service_func2) (void *);&#125; g_dlib_manager;/* g_dlib_manager作为动态库接口的全局变量 */struct dlib_manager *g_dlib_manager;// (2)c利用dlopen、dlsym等来加载动态库，更新接口。重新申请新的内存，来保存新的动态库接口：/* 更新动态库接口 */struct dlib_manager *new_manager = malloc(sizeof(*new_manager));new_manager-&gt;dlib_handle = dlopen(&quot;libupgrade.so&quot;, RTLD_LAZY);new_manager-&gt;service_func = dlsym(g_dlib_handle, &quot;service_call&quot;);new_manager-&gt;service_func2 = dlsym(g_dlib_handle, &quot;service_call2&quot;);/* 在多核环境下，使用内存屏障，以保证在交换new_manager和g_dlib_manager时，new_manager已经完成了赋值 */wmb();// 交换新指针与当前正在使用的接口指针，因为目前，无论是新指针还是旧指针都是有效的接口，所以并不会对业务产生影响swap(new_manager, g_dlib_manager);// 交换完成以后，新的请求都会交由新接口来处理。由于当前旧接口仍然可能正在使用中，所以要使用推迟释放或是等待正在服务的接口完成delay_free(new_manager);// (3) 在调用服务接口时，要利用局部变量保存服务接口：/** 之所以这里使用局部变量来进行接口调用，是为了避免在调用了一部分接口后，g_dlib_manager才发生更新，* 从而导致前后的服务接口属于不同的动态库，造成不可预料的问题。通过临时变量来保存服务接口，能确保所有接口的一致性。*/struct dlib_manager *local_dlib_manager = g_dlib_manager;local_dlib_manager-&gt;service_func1(data);local_dlib_manager-&gt;service_func2(data);/** 释放旧接口的关键在于，要保证没有旧接口正在被使用。根据自己的业务，找到一个时间点——在这个时间点上，* 所有的线程（准确地说是请求流程）都已经服务过一次。这时，新来的请求就会使用新的接口，* 于是我们也就可以安全地释放旧接口了。其实整个实现方案是借鉴了Linux内核的RCU实现方式。* 通过这种方法，可以进行“平滑无缝”的升级，而不影响运行状态下的业务功能。*/

内存问题内存泄漏对于良好的代码风格，有一项很重要的要求是一个函数只专注于做一件事情。如果该函数像瑞士军刀一样能实现多个功能，那基本上可以断言这不是一个设计良好的函数。C库中的realloc函数就是一个典型的反面教材：
#include &lt;stdlib.h&gt;/** 参数ptr为NULL，而size不为0，则等同于malloc（size）。* 参数ptr不为NULL，而size为0，则等同于free（ptr）。* 参数ptr和size均不为0，其行为类似于free（ptr）；malloc（size）。*/void *realloc(void *ptr, size_t size);/** 这里就会因为realloc的第三种行为引入一个bug。当realloc分配内存失败的时候，ptr会返回NULL。* 但是这时ptr原来指向的内存并没有被释放，而ptr却已经被赋值为NULL了，这就造成了ptr原有内存泄漏。*/void * ptr = realloc(ptr, new_size);if (!ptr) &#123;    //错误处理&#125;/** realloc只有在分配内存成功的情况下，才会让ptr等于new_ptr。* 这样，在分配内存失败的情况下，ptr指向的内存并不会丢失。* realloc使用不当还会引发其他几种bug，在此就不一一罗列了。* 需要吸取的教训就是，慎用realloc，甚至最好不用realloc。如果真的需要使用realloc，* 一定要确保在realloc的三种行为下代码都可以正常工作。*/void * new_ptr = realloc(ptr, new_size);if (!new_ptr) &#123;    //错误处理&#125;ptr = new_ptr

内存越界通过良好的编程习惯基本上是可以避免内存越界问题的。防范的根本思想在于在对缓冲区（一般为数组）进行拷贝前，要保证复制的长度不要超过缓冲区的空间大小。比如在memcpy前，要检查目的地址是否有足够的空间。使用宏或sizeof可保证缓冲长度的一致性；
// 当缓冲大小改变为32的时候，需要改动两处代码。一旦忘记修改memcpy处的拷贝长度，就会造成内存越界。// bad codechar dst_buf[64];memcpy(dst_buf, src_buf,64);// 这样就可以做到缓存大小和复制长度的同步修改。// good code#define BUF_SIZE    64char dst_buf[BUF_SIZE];memcpy(dst_buf, src_buf, BUF_SIZE);// good codechar dst_buf[64];memcpy(dst_buf, src_buf, sizeof(dst_buf));

使用安全的库函数也可以保证复制的长度不超过缓冲区的空间，下面来介绍4种库函数。
1）使用strncat代替strcat，代码如下：
#include &lt;string.h&gt;char *strncat(char *dest, const char *src, size_t n);

从src中最多追加n个字符到dest字符串的后面。需要注意的是，当src包含n个以上的字符时，dest的空间至少为strlen（dest）+n+1，因为该函数还会追加字符串结束符&#39;\0&#39;到dest后面。
2）使用strncpy代替strcpy，代码如下：
#include &lt;string.h&gt;char *strncpy(char *dest, const char *src, size_t n);

从src中最多复制n个字符到dest字符串中。与strncat相同的是，当src包含n个以上的字符时，dest的空间需要为n+1，因为该函数还会再复制一个字符串结束符&#39;\0&#39;。
3）使用snprintf代替sprintf，代码如下：
#include &lt;stdio.h&gt;int snprintf(char *str, size_t size, const char *format, ...);

snprintf比前面两个函数strncat和strncpy更为友好，在往str中写数据时，最多会写入n字节，其中已包括字符串结束符’\0’。
4）使用fgets代替gets，代码如下：
#include &lt;stdio.h&gt;char *fgets(char *s, int size, FILE *stream);

危险的gets函数从来不检查缓冲区的大小，并且还是从标准输入中读取数据，这是极其危险的行为。再大的缓存空间也无法满足永无终止的标准输入，因此一定要使用fgets代替。fgets最多会复制size-1字节到缓存s中，并且会在最后一个字符后面追加&#39;\0&#39;。

由于历史原因，标准C库中还存在其他不安全的接口，不过后来C库中也发展了相应的安全接口。在日常的编程中，除非特殊情况，都要使用安全函数来替代非安全函数的调用。

内存检查工欲善其事，必先利其器。valgrind作为一个免费且优秀的工具包，提供了很多有用的功能，其中最有名的就是对内存问题的检测和定位。
#include &lt;stdlib.h&gt;#include &lt;stdio.h&gt;#include &lt;string.h&gt;static void mem_leak1(void)&#123;    char *p = malloc(1);&#125;static void mem_leak2(void)&#123;    FILE *fp = fopen(&quot;test.txt&quot;, &quot;w&quot;);&#125;static void mem_overrun1(void)&#123;    char *p = malloc(1);    *(short*)p = 2;    free(p);&#125;static void mem_overrun2(void)&#123;    char array[5];    strcpy(array, &quot;hello&quot;);&#125;static void mem_double_free(void)&#123;    char *p = malloc(1);    free(p);    free(p);&#125;static void mem_free_wild_pointer(void)&#123;    char *p;    free(p);&#125;int main()&#123;    mem_leak1();    mem_leak2();    mem_overrun1();    mem_overrun2();    mem_double_free();    mem_free_wild_pointer();    return 0;&#125;

上面的代码中包含了六种常见的内存问题：

动态内存泄漏；
资源泄漏，代码中以文件描述符为例；
动态内存越界；
数组越界；
动态内存double free；
使用野指针。

