这只是一个简单的示例程序，即使没有valgrind，我们也可以很轻易地发现问题。但是在真实的项目中，当代码量达到万行、十万行甚至百万行时，由于申请的内存可能不是在一个地方被使用，它不可避免地会被传来传去。这时，如果只是靠review代码来检查问题，可能很难找到根本原因，而使用valgrind则可以很容易地发现问题所在。
当然，valgrind也不是万能的。笔者就遇到过valgrind无法找到问题，最后是通过不断地检查代码才找到症结所在的情况。发现问题，再解决问题，毕竟是末流。最好的方法，就是从一开始就不引入问题，防微杜渐。这点可以通过良好的代码风格和设计来实现。写代码不是一件容易的事情，要用心，把代码当作自己的作品，真心地去写好它。这样，自然而然的就会把代码写好。
长跳转setjmp与longjmp#include &lt;setjmp.h&gt;/** setjmp用于保存当前栈的上下文，将其保存到参数env中。* 若返回0值，则为setjmp直接返回的结果；若返回非0值，则为从longjmp恢复栈空间时返回的结果。*/int setjmp(jmp_buf env);/** longjmp用于将上下文恢复至env保存的状态，参数val用于作为恢复点setjmp的返回值。* 一般情况下，保存的jmp_buf env为全局变量。跳转一次后，保存的env上下文环境就会失效。请看下面的示例：*/void longjmp(jmp_buf env, int val);

#include &lt;stdlib.h&gt;#include &lt;stdio.h&gt;#include &lt;setjmp.h&gt;static jmp_buf g_stack_env;static void func1(void);static void func2(void);int main(void)&#123;    if (0 == setjmp(g_stack_env)) &#123;        printf(&quot;Normal flow\n&quot;);        func1();    &#125; else &#123;        printf(&quot;Longjump flow\n&quot;);    &#125;    return 0;&#125;static void func1(void)&#123;    printf(&quot;Enter func1\n&quot;);    func2();&#125;static void func2(void)&#123;    printf(&quot;Enter func2\n&quot;);    longjmp(g_stack_env, 1);    printf(&quot;Leave func2\n&quot;);&#125;// outputNormal flowEnter func1Enter func2Longjump flow

在main函数中，使用setjmp将当前的栈环境保存到g_stack_env中，然后调用func1-&gt;func2，在func2中，使用longjmp来恢复保存的栈环境g_stack_env，从而完成“长跳转”。
长跳转机制setjmp和longjmp分别用于保存和恢复栈的上下文，来实现长跳转。而栈的实现肯定是与平台相关的，因此setjmp和longjmp的实现也是与平台相关的。
/* Calling environment, plus possibly a saved signal mask.  */struct __jmp_buf_tag  &#123;    /* NOTE: The machine-dependent definitions of `__sigsetjmp&#x27;       assume that a `jmp_buf&#x27; begins with a `__jmp_buf&#x27; and that `__mask_was_saved&#x27; follows it.  Do not move these members or add others before it.  */    __jmp_buf __jmpbuf;     /* Calling environment.  */    int __mask_was_saved;   /* Saved the signal mask?  */    __sigset_t __saved_mask;    /* Saved signal mask.  */  &#125;;  typedef struct __jmp_buf_tag jmp_buf[1];

x86平台的__jmp_buf的定义为：
# if __WORDSIZE == 64typedef long int __jmp_buf[8];# elif defined  __x86_64__typedef long long int __jmp_buf[8];# elsetypedef int __jmp_buf[6];# endif

x86平台的setjmp和longjmp的实现均位于glibc-2.17/sysdeps/i386/setjmp.S中。
ENTRY (BP_SYM (__sigsetjmp))    ENTER    /* 将jmpbuf的地址赋给eax */    movl JMPBUF(%esp), %eax    CHECK_BOUNDS_BOTH_WIDE (%eax, JMPBUF(%esp), $JB_SIZE)    /* 保存寄存器 */    movl %ebx, (JB_BX*4)(%eax)    movl %esi, (JB_SI*4)(%eax)    movl %edi, (JB_DI*4)(%eax)    leal JMPBUF(%esp), %ecx /* Save SP as it will be after we return.  */#ifdef PTR_MANGLE    PTR_MANGLE (%ecx)#endif    movl %ecx, (JB_SP*4)(%eax)    movl PCOFF(%esp), %ecx  /* Save PC we are returning to now.  */    LIBC_PROBE (setjmp, 3, 4@%eax, -4@SIGMSK(%esp), 4@%ecx)#ifdef PTR_MANGLE    PTR_MANGLE (%ecx)#endifmovl %ecx, (JB_PC*4)(%eax)    LEAVE /* pop frame pointer to prepare for tail-call.  */    movl %ebp, (JB_BP*4)(%eax) /* Save caller&#x27;s frame pointer.  */#if defined NOT_IN_libc &amp;&amp; defined IS_IN_rtld    /* In ld.so we never save the signal mask.  */    xorl %eax, %eax    ret#else    /* Make a tail call to __sigjmp_save; it takes the same args.  */    jmp __sigjmp_save#endifEND (BP_SYM (__sigsetjmp))

上面的汇编代码，主要是将寄存器EBX、ESI、EDI、ESP、PC和EBP寄存器保存到jmp_buf中。回想前面__jmp_buf的定义，它在x86_32位平台上是大小为6的int型数组，正好用于保存这6个寄存器。
看完了__sigsetjmp的实现，自然就轮到longjmp了：
ENTRY (__longjmp)    movl 4(%esp), %ecx  /* User&#x27;s jmp_buf in %ecx.  */    movl 8(%esp), %eax  /* Second argument is return value.  */    /* Save the return address now.  */    movl (JB_PC*4)(%ecx), %edx    LIBC_PROBE (longjmp, 3, 4@%ecx, -4@%eax, 4@%edx)    /* 恢复保存的寄存器  */    movl (JB_BX*4)(%ecx), %ebx    movl (JB_SI*4)(%ecx), %esi    movl (JB_DI*4)(%ecx), %edi    movl (JB_BP*4)(%ecx), %ebp    movl (JB_SP*4)(%ecx), %esp    LIBC_PROBE (longjmp_target, 3, 4@%ecx, -4@%ecx, 4@%edx)    /* Jump to saved PC.  */    jmp *%edxEND (__longjmp)

setjmp保存寄存器的内容，longjmp自然是恢复寄存器的内容。上面的代码很简单，把寄存器PC、EBX、ESI、EDI、EBP和ESP的内容恢复后，将第二个参数val保存到EAX中，最后跳转到恢复的PC寄存器处——也就是setjmp的下一条指令的位置。
长跳转陷阱longjmp的man手册给出了如下说明：
当满足以下条件时，局部变量的值是不能确定的：

它们是调用setjmp所在函数的局部变量。
其值在setjmp和longjmp之间有变化。
它们没有被声明为volatile变量。

#include &lt;stdlib.h&gt;#include &lt;stdio.h&gt;#include &lt;setjmp.h&gt;static jmp_buf g_stack_env;static void func1(int *a, int *b, int *c);int main(void)&#123;    int a = 1;    int b = 2;    int c = 3;    int ret = setjmp(g_stack_env);    if (0 == ret) &#123;        printf(&quot;Normal flow\n&quot;);        printf(&quot;a = %d, b = %d, c = %d\n&quot;, a, b, c);        func1(&amp;a, &amp;b, &amp;c);    &#125; else &#123;        printf(&quot;Longjump flow\n&quot;);        printf(&quot;a = %d, b = %d, c = %d\n&quot;, a, b, c);&#125;    return 0;&#125;static void func1(int *a, int *b, int *c)&#123;    printf(&quot;Enter func1\n&quot;);    ++(*a);    ++(*b);    ++(*c);    printf(&quot;func1: a = %d, b = %d, c = %d\n&quot;, *a, *b, *c);    longjmp(g_stack_env, 1);    printf(&quot;Leave func1\n&quot;);&#125;// 从结果上看，变量a、b、c的值均没有被恢复。这点符合我们的预期，毕竟longjmp只是恢复了6个寄存器的内容。# gcc 4_7_3_longjmp_var.c -Wall# ./a.outNormal flowa = 1, b = 2, c = 3Enter func1func1: a = 2, b = 3, c = 4Longjump flowa = 2, b = 3, c = 4// 然而当我们加上编译选项-O2以后，结果就完全不同了。在longjmp跳转以后，a、b和c的值仍然是原来的值。/*在 -O2 优化级别下，编译器会执行大量的优化，例如：    消除重复计算（Common Subexpression Elimination）    死代码消除（Dead Code Elimination）    循环优化（Loop Optimization）    寄存器分配优化    函数内联（Inline Functions）*/[fgao@ubuntu chapter3]#gcc 4_7_3_longjmp_var.c -Wall -O2[fgao@ubuntu chapter3]#./a.outNormal flowa = 1, b = 2, c = 3Enter func1func1: a = 2, b = 3, c = 4Longjump flowa = 1, b = 2, c = 3

除了上面这个缺陷以外，如果我们的思维再开阔些，还能发现由longjmp实现原理引发的其他缺陷。比如因为它不能处理局部变量的问题，因此在C++中局部变量的析构肯定也是有问题的。
#include &lt;setjmp.h&gt;#include &lt;iostream&gt;using namespace std;static jmp_buf g_stack_env;static void func1(void);class Test &#123;public:    Test() &#123;        cout &lt;&lt; &quot;Constructor&quot; &lt;&lt; endl;    &#125;    ~Test() &#123;        cout &lt;&lt; &quot;Destructor&quot; &lt;&lt; endl;    &#125;&#125;;int main(void)&#123;    int ret = setjmp(g_stack_env);    if (0 == ret) &#123;        cout &lt;&lt; &quot;Normal flow&quot; &lt;&lt; endl;        func1();    &#125; else &#123;        cout &lt;&lt; &quot;Longjump flow&quot; &lt;&lt; endl;    &#125;&#125;// output# g++ 4_7_3_longjmp_destructor.cpp -Wall# ./a.outNormal flowEnter func1ConstructorLongjump flow

进程概念进程是操作系统的一个核心概念。每个进程都有自己唯一的标识：进程ID，也有自己的生命周期。

进程 IDLinux下每个进程都会有一个非负整数表示的唯一进程ID，简称pid。Linux提供了getpid函数来获取进程的pid，同时还提供了getppid函数来获取父进程的pid，相关接口定义如下：
#include &lt;sys/types.h&gt;#include &lt;unistd.h&gt;pid_t getpid(void);pid_t getppid(void);

每个进程都有自己的父进程，父进程又会有自己的父进程，最终都会追溯到1号进程即init进程。这就决定了操作系统上所有的进程必然会组成树状结构，就像一个家族的家谱一样。可以通过pstree的命令来查看进程的家族树。
procfs文件系统会在&#x2F;proc下为每个进程创建一个目录，名字是该进程的pid。目录下有很多文件，用于记录进程的运行情况和统计信息等，如下所示：
ll /proc总用量 0dr-xr-xr-x  9 root       root          0  4月  1 06:56 1dr-xr-xr-x  9 root       root          0  4月  1 06:56 10dr-xr-xr-x  9 root       root          0  4月  1 06:56 100dr-xr-xr-x  9 root       root          0  4月  1 06:56 101dr-xr-xr-x  9 root       root          0  4月  1 06:56 102dr-xr-xr-x  9 root       root          0  4月  1 06:56 103dr-xr-xr-x  9 root       root          0  4月  1 06:56 1039dr-xr-xr-x  9 root       root          0  4月  1 06:56 104......

因为进程有创建，也有终止，所以&#x2F;proc&#x2F;下记录进程信息的目录（以及目录下的文件）也会发生变化。操作系统必须保证在任意时刻都不能出现两个进程有相同pid的情况。虽然进程ID是唯一的，但是进程ID可以重用。进程退出以后，其进程ID还可以再次分配给其他的进程使用。
Linux分配进程ID的算法不同于给进程分配文件描述符的最小可用算法，它采用了延迟重用的算法，即分配给新创建进程的ID尽量不与最近终止进程的ID重复，这样就可以防止将新创建的进程误判为使用相同进程ID的已经退出的进程。
那么如何实现延迟重用呢？内核采用的方法如下：
1）位图记录进程ID的分配情况（0为可用，1为已占用）。
2）将上次分配的进程ID记录到last_pid中，分配进程ID时，从last_pid+1开始找起，从位图中寻找可用的ID。
3）如果找到位图集合的最后一位仍不可用，则回滚到位图集合的起始位置，从头开始找。
既然是位图记录进程ID的分配情况，那么位图的大小就必须要考虑周全。位图的大小直接决定了系统允许同时存在的进程的最大个数，这个最大个数在系统中称为pid_max。上面的第3步提到，回绕到位图集合的起始位置，从头寻找可用的进程ID。事实上，严格说来，这种说法并不正确，回绕时并不是从0开始找起，而是从300开始找起。内核在kernel&#x2F;pid.c文件中定义了RESERVED_PIDS，其值是300，300以下的pid会被系统占用，而不能分配给用户进程：
define RESERVED_PIDS       300int pid_max = PID_MAX_DEFAULT;

Linux系统下可以通过procfs或sysctl命令来查看pid_max的值：
manu@manu-rush:~$ cat /proc/sys/kernel/pid_max131072manu@manu-rush:~$ sysctl kernel.pid_maxkernel.pid_max = 131072# 其实，此上限值是可以调整的，系统管理员可以通过如下方法来修改此上限值：root@manu-rush:~# sysctl -w kernel.pid_max=4194304kernel.pid_max = 4194304# 但是内核自己也设置了硬上限，如果尝试将pid_max的值设成一个大于硬上限的值就会失败。root@manu-rush:~# sysctl -w kernel.pid_max=4194305error: &quot;Invalid argument&quot; setting key &quot;kernel.pid_max&quot;

从上面的操作可以看出，Linux系统将系统进程数的硬上限设置为4194304（4M）。内核又是如何决定系统进程个数的硬上限的呢？对此，内核定义了如下的宏：
#define PID_MAX_LIMIT (CONFIG_BASE_SMALL ? PAGE_SIZE * 8 : \    (sizeof(long) &gt; 4 ? 4 * 1024 * 1024 :PID_MAX_DEFAULT))

从上面代码中可以看出决定系统进程个数硬上限的逻辑为：

如果选择了CONFIG_BASE_SMALL编译选项，则为页面（PAGE_SIZE）的位数。
如果选择了CONFIG_BASE_FULL编译选项，那么：
对于32位系统，系统进程个数硬上限为32768（即32K）。
对于64位系统，系统进程个数硬上限为4194304（即4M）。



通过上面的讨论可以看出，在64位系统中，系统容许创建的进程的个数超过了400万，这个数字是相当庞大的，足够应用层使用。对于单线程的程序，进程ID比较好理解，就是唯一标识进程的数字。对于多线程的程序，每一个线程调用getpid函数，其返回值都是一样的，即进程的ID。
进程层次每个进程都有父进程，父进程也有父进程，这就形成了一个以init进程为根的家族树。除此以外，进程还有其他层次关系：进程、进程组和会话。进程组和会话在进程之间形成了两级的层次：进程组是一组相关进程的集合，会话是一组相关进程组的集合。
这样说来，一个进程会有如下ID：

PID：进程的唯一标识。对于多线程的进程而言，所有线程调用getpid函数会返回相同的值。
PGID：进程组ID。每个进程都会有进程组ID，表示该进程所属的进程组。默认情况下新创建的进程会继承父进程的进程组ID。
SID：会话ID。每个进程也都有会话ID。默认情况下，新创建的进程会继承父进程的会话ID。

可以调用如下指令来查看所有进程的层次关系：
$ ps -ejH$ ps axjf

对于进程而言，可以通过如下函数调用来获取其进程组ID和会话ID。
#include &lt;unistd.h&gt;pid_t getpgrp(void);pid_t getsid(pid_t pid);

前面提到过，新进程默认继承父进程的进程组ID和会话ID，如果都是默认情况的话，那么追根溯源可知，所有的进程应该有共同的进程组ID和会话ID。但是调用ps axjf可以看到，实际情况并非如此，系统中存在很多不同的会话，每个会话下也有不同的进程组。
进程组和会话是为了支持shell作业控制而引入的概念。当有新的用户登录Linux时，登录进程会为这个用户创建一个会话。用户的登录shell就是会话的首进程。会话的首进程ID会作为整个会话的ID。会话是一个或多个进程组的集合，囊括了登录用户的所有活动。
在登录shell时，用户可能会使用管道，让多个进程互相配合完成一项工作，这一组进程属于同一个进程组。当用户通过SSH客户端工具连入Linux时，与上述登录的情景是类似的。
进程组修改进程组ID的接口如下：
#include &lt;unistd.h&gt;/** 这个函数的含义是，找到进程ID为pid的进程，将其进程组ID修改为pgid，* 如果pid的值为0，则表示要修改调用进程的进程组ID。该接口一般用来创建一个新的进程组。*/int setpgid(pid_t pid, pid_t pgid);/** 下面三个接口含义一致，都是创立新的进程组，并且指定的进程会成为进程组的首进程。* 如果参数pid和pgid的值不匹配，那么setpgid函数会将一个进程从原来所属的进程组迁移到pgid对应的进程组。*/setpgid(0,0)setpgid(getpid(),0)setpgid(getpid(),getpid())

setpgid函数有很多限制：

pid参数必须指定为调用setpgid函数的进程或其子进程，不能随意修改不相关进程的进程组ID，如果违反这条规则，则返回-1，并置errno为ESRCH。
pid参数可以指定调用进程的子进程，但是子进程如果已经执行了exec函数，则不能修改子进程的进程组ID。如果违反这条规则，则返回-1，并置errno为EACCESS。
在进程组间移动，调用进程，pid指定的进程及目标进程组必须在同一个会话之内。如果违反这条规则，则返回-1，并置errno为EPERM。
pid指定的进程，不能是会话首进程。如果违反这条规则，则返回-1，并置errno为EPERM。

有了创建进程组的接口，新创建的进程组就不必继承父进程的进程组ID了。最常见的创建进程组的场景就是在shell中执行管道命令，代码如下：
cmd1 | cmd2 | cmd3

下面用一个最简单的命令来说明，其进程之间的关系如图:
ps ax|grep nfsd


ps进程和grep进程都是bash创建的子进程，两者通过管道协同完成一项工作，它们隶属于同一个进程组，其中ps进程是进程组的组长。
引入了进程组的概念，可以更方便地管理这一组进程了。比如这项工作放弃了，不必向每个进程一一发送信号，可以直接将信号发送给进程组，进程组内的所有进程都会收到该信号。

前文曾提到过，子进程一旦执行exec，父进程就无法调用setpgid函数来设置子进程的进程组ID了，这条规则会影响shell的作业控制。出于保险的考虑，一般父进程在调用fork创建子进程后，会调用setpgid函数设置子进程的进程组ID，同时子进程也要调用setpgid函数来设置自身的进程组ID。这两次调用有一次是多余的，但是这样做能够保证无论是父进程先执行，还是子进程先执行，子进程一定已经进入了指定的进程组中。由于fork之后，父子进程的执行顺序是不确定的，因此如果不这样做，就会造成在一定的时间窗口内，无法确定子进程是否进入了相应的进程组。

可以通过跟踪bash进程的系统调用来证明这一点，下面的2258进程是bash，我们在该bash上执行sleep 200，在执行之前，在另一个终端用strace跟踪bash的系统调用，可以看到，父进程和子进程都执行了一遍setpgid函数，代码如下所示：
manu@manu-hacks:~$ sudo strace -f -p 2258Process 2258 attached    ．．．/*父进程调用setpgid函数*/[pid  2258] setpgid(2509, 2509 &lt;unfinished ...&gt;．．．/*子进程调用setpgid函数*/[pid  2509] setpgid(2509, 2509 &lt;unfinished ...&gt;．．．/*子进程执行execve*/[pid  2509] execve(&quot;/bin/sleep&quot;, [&quot;sleep&quot;, &quot;200&quot;], [/* 31 vars */]) = 0．．．

用户在shell中可以同时执行多个命令。对于耗时很久的命令（如编译大型工程），用户不必傻傻等待命令运行完毕才执行下一个命令。用户在执行命令时，可以在命令的结尾添加“&amp;”符号，表示将命令放入后台执行。这样该命令对应的进程组即为后台进程组。在任意时刻，可能同时存在多个后台进程组，但是不管什么时候都只能有一个前台进程组。只有在前台进程组中进程才能在控制终端读取输入。当用户在终端输入信号生成终端字符（如ctrl+c、ctrl+z、ctr+\等）时，对应的信号只会发送给前台进程组。
shell中可以存在多个进程组，无论是前台进程组还是后台进程组，它们或多或少存在一定的联系，为了更好地控制这些进程组（或者称为作业），系统引入了会话的概念。会话的意义在于将很多的工作囊括在一个终端，选取其中一个作为前台来直接接收终端的输入及信号，其他的工作则放在后台执行。
会话会话是一个或多个进程组的集合，以用户登录系统为例：

系统提供setsid函数来创建会话，其接口定义如下：
#include &lt;unistd.h&gt;pid_t setsid(void);

如果这个函数的调用进程不是进程组组长，那么调用该函数会发生以下事情：
1）创建一个新会话，会话ID等于进程ID，调用进程成为会话的首进程。
2）创建一个进程组，进程组ID等于进程ID，调用进程成为进程组的组长。
3）该进程没有控制终端，如果调用setsid前，该进程有控制终端，这种联系就会断掉。
调用setsid函数的进程不能是进程组的组长，否则调用会失败，返回-1，并置errno为EPERM。这个限制是比较合理的。如果允许进程组组长迁移到新的会话，而进程组的其他成员仍然在老的会话中，那么，就会出现同一个进程组的进程分属不同的会话之中的情况，这就破坏了进程组和会话的严格的层次关系了。Linux提供了setsid命令，可以在新的会话中执行命令，通过该命令可以很容易地验证上面提到的三点：
$ setsid sleep 100$ ps ajxfPPID   PID  PGID   SID TTY      TPGID STAT   UID   TIME COMMAND…1     4469  4469  4469 ?           -1   Ss   1000   0:00 sleep 100

从输出中可以看出，系统创建了新的会话4469，新的会话下又创建了新的进程组，会话ID和进程组ID都等于进程ID，而该进程已经不再拥有任何控制终端了（TTY对应的值为“？”表示进程没有控制终端）。常用的调用setsid函数的场景是login和shell。除此以外创建daemon进程也要调用setsid函数。
进程创建forkLinux系统下，进程可以调用fork函数来创建新的进程。调用进程为父进程，被创建的进程为子进程。
#include &lt;unistd.h&gt;pid_t fork(void);

与普通函数不同，fork函数会返回两次。一般说来，创建两个完全相同的进程并没有太多的价值。大部分情况下，父子进程会执行不同的代码分支。fork函数的返回值就成了区分父子进程的关键。fork函数向子进程返回0，并将子进程的进程ID返给父进程。当然了，如果fork失败，该函数则返回-1，并设置errno。
常见的出错情景如表：

ret = fork();if(ret == 0)&#123;    …//此处是子进程的代码分支&#125;else if(ret &gt; 0)&#123;    …//此处是父进程的代码分支&#125;else&#123;     …// fork失败，执行error handle&#125;


fork可能失败。检查返回值进行正确的出错处理，是一个非常重要的习惯。设想如果fork返回-1，而程序没有判断返回值，直接将-1当成子进程的进程号，那么后面的代码执行kill（child_pid，9）就相当于执行kill（-1，9）。这会发生什么？后果是惨重的，它将杀死除了init以外的所有进程，只要它有权限。

从内核2.6.32开始，在默认情况下，父进程将成为fork之后优先调度的对象。采取这种策略的原因是：fork之后，父进程在CPU中处于活跃的状态，并且其内存管理信息也被置于硬件内存管理单元的转译后备缓冲器（TLB），所以先调度父进程能提升性能。从2.6.24起，Linux采用完全公平调度（Completely Fair Scheduler，CFS）。用户创建的普通进程，都采用CFS调度策略。对于CFS调度策略，procfs提供了如下控制选项：
/proc/sys/kernel/sched_child_runs_first

该值默认是0，表示父进程优先获得调度。如果将该值改成1，那么子进程会优先获得调度。POSIX标准和Linux都没有保证会优先调度父进程。因此在应用中，决不能对父子进程的执行顺序做任何的假设。如果确实需要某一特定执行的顺序，那么需要使用进程间同步的手段。

从 Linux 内核版本 5.9 开始，kernel.sched_child_runs_first 参数被移除了。在移除该参数后，内核默认的行为是 父进程在 fork() 后优先运行，并且无法通过参数进行更改。

fork之后的子进程完全拷贝了父进程的地址空间，包括栈、堆、代码段等。通过下面的示例代码，我们一起来查看父子进程的内存关系：
#include &lt;stdio.h&gt;#include &lt;stdlib.h&gt;#include &lt;unistd.h&gt;#include &lt;string.h&gt;#include &lt;errno.h&gt;#include &lt;sys/types.h&gt;#include &lt;wait.h&gt;int g_int = 1;int main()&#123;    int local_int = 1;    int *malloc_int = malloc(sizeof(int));    *malloc_int = 1;    pid_t pid = fork();    if(pid == 0) /*子进程*/    &#123;        local_int = 0;        g_int = 0;        *malloc_int = 0;        fprintf(stderr,&quot;[CHILD ] child change local global malloc value to 0\n&quot;);        free(malloc_int);        sleep(10);        fprintf(stderr,&quot;[CHILD ] child exit\n&quot;);        exit(0);    &#125;    else if(pid &lt; 0)    &#123;        printf(&quot;fork failed (%s)&quot;,strerror(errno));        return 1;    &#125;    fprintf(stderr,&quot;[PARENT] wait child exit\n&quot;);    waitpid(pid,NULL,0);    fprintf(stderr,&quot;[PARENT] child have exit\n&quot;);    printf(&quot;[PARENT] g_int = %d\n&quot;,g_int);    printf(&quot;[PARENT] local_int = %d\n&quot;,local_int);    printf(&quot;[PARENT] malloc_int = %d\n&quot;,local_int);    free(malloc_int);    return 0;&#125;// output[PARENT] wait child exit[CHILD ] child change local global malloc value to 0[CHILD ] child exit[PARENT] child have exit[PARENT] g_int = 1[PARENT] local_int = 1[PARENT] malloc_int = 1

这里刻意定义了三个变量，一个是位于数据段的全局变量，一个是位于栈上的局部变量，还有一个是通过malloc动态分配位于堆上的变量，三者的初始值都是1。然后调用fork创建子进程，子进程将三个变量的值都改成了0。按照fork的语义，子进程完全拷贝了父进程的数据段、栈和堆上的内存，如果父子进程对相应的数据进行修改，那么两个进程是并行不悖、互不影响的。因此，在上面示例代码中，尽管子进程将三个变量的值都改成了0，对父进程而言这三个值都没有变化，仍然是1，代码的输出也证实了这一点。
前文提到过，子进程和父进程执行一模一样的代码的情形比较少见。Linux提供了execve系统调用，构建在该系统调用之上，glibc提供了exec系列函数。这个系列函数会丢弃现存的程序代码段，并构建新的数据段、栈及堆。调用fork之后，子进程几乎总是通过调用exec系列函数，来执行新的程序。在这种背景下，fork时子进程完全拷贝父进程的数据段、栈和堆的做法是不明智的，因为接下来的exec系列函数会毫不留情地抛弃刚刚辛苦拷贝的内存。为了解决这个问题，Linux引入了写时拷贝（copy-on-write）的技术。
写时拷贝是指子进程的页表项指向与父进程相同的物理内存页，这样只拷贝父进程的页表项就可以了，当然要把这些页面标记成只读。如果父子进程都不修改内存的内容，大家便相安无事，共用一份物理内存页。但是一旦父子进程中有任何一方尝试修改，就会引发缺页异常（page fault）。此时，内核会尝试为该页面创建一个新的物理页面，并将内容真正地复制到新的物理页面中，让父子进程真正地各自拥有自己的物理内存页，然后将页表中相应的表项标记为可写。

从上面的描述可以看出，对于没有修改的页面，内核并没有真正地复制物理内存页，仅仅是复制了父进程的页表。这种机制的引入提升了fork的性能，从而使内核可以快速地创建一个新的进程。
Linux的内存管理使用的是四级页表，如图4-6所示，看了四级页表的名字，也就不难推测图中那些函数的作用了。


在最后的copy_one_pte函数中有如下代码：
/*如果是写时拷贝，那么无论是初始页表，还是拷贝的页表，都设置了写保护 *后面无论父子进程，修改页表对应位置的内存时，都会触发page fault */ if (is_cow_mapping(vm_flags)) &#123;     ptep_set_wrprotect(src_mm, addr, src_pte);     pte = pte_wrprotect(pte); &#125;

该代码将页表设置成写保护，父子进程中任意一个进程尝试修改写保护的页面时，都会引发缺页中断，内核会走向do_wp_page函数，该函数会负责创建副本，即真正的拷贝。写时拷贝技术极大地提升了fork的性能，在一定程度上让vfork成为了鸡肋。

执行fork函数，内核会复制父进程所有的文件描述符。对于父进程打开的所有文件，子进程也是可以操作的。那么父子进程同时操作同一个文件是并行不悖的，还是互相影响的呢？
下面通过对一个例子的讨论来说明这个问题。read函数并没有将偏移量作为参数传入，但是每次调用read函数或write函数时，却能够接着上次读写的位置继续读写。原因是内核已经将偏移量的信息记录在与文件描述符相关的数据结构里了。那么问题来了，父子进程是共用一个文件偏移量还是各有各的文件偏移量呢？
#include &lt;stdio.h&gt;#include &lt;string.h&gt;#include &lt;strings.h&gt;#include &lt;unistd.h&gt;#include &lt;sys/types.h&gt;#include &lt;sys/stat.h&gt;#include &lt;fcntl.h&gt;#include &lt;errno.h&gt;#define INFILE &quot;./in.txt&quot;#define OUTFILE &quot;./out.txt&quot;#define MODE  S_IRUSR |S_IWUSR|S_IRGRP|S_IWGRP|S_IROTHint main(void)&#123;    int fd_in,fd_out;    char buf[1024];    memset(buf, 0, 1024);    fd_in = open(INFILE, O_RDONLY);    if(fd_in &lt; 0 )    &#123;        fprintf(stderr,&quot;failed to open %s, reason(%s)\n&quot;, INFILE,strerror(errno));        return 1;    &#125;    fd_out = open(OUTFILE,O_WRONLY|O_CREAT|O_TRUNC,MODE);    if(fd_out &lt; 0)    &#123;        fprintf(stderr,&quot;failed to open %s, reason(%s)\n&quot;, OUTFILE,strerror(errno));        return 1;    &#125;    fork();/*此处忽略错误检查*/    while(read(fd_in, buf, 2) &gt; 0)    &#123;        printf(&quot;%d: %s&quot;,getpid(),buf);        sprintf(buf, &quot;%d Hello,World!\n&quot;,getpid());        write(fd_out,buf,strlen(buf));        sleep(1);        memset(buf, 0, 1024);    &#125;&#125;

INFILE的内容是：
123456

上面的程序中，父子进程都会去读INFILE，如果父子进程各维护各的文件偏移量，那么父子进程都会打印出1~6。事实如何呢？请看输出内容：
$ ./fork_file6610: 16611: 26610: 36611: 46610: 56611: 56610: 6

如果父子进程各自维护自己的文件偏移量，那么一定是打印出两套1~6，但是事实并非如此。无论父进程还是子进程调用read函数导致文件偏移量后移都会被对方获知，这表明父子进程共用了一套文件偏移量。对于第二个输出，为什么父子进程都打印5呢？这是因为我的机器是多核的，父子进程同时执行，发现当前文件偏移量是4*2，然后各自去读了第8和第9字节，也就是“5\n”。写文件也是一样，如果fork之前打开了某文件，之后父子进程写入同一个文件描述符而又不采取任何同步的手段，那么就会因为共享文件偏移量而使输出相互混合，不可阅读。
文件描述符还有一个文件描述符标志（file descriptor flag）。目前只定义了一个标志位：FD_CLOSEXEC，这是close_on_exec标志位。细心阅读open函数手册也会发现，open函数也有一个类似的标志位，即O_CLOSEXEC，该标志位也是用于设置文件描述符标志的。那么这个标志位到底有什么作用呢？如果文件描述符中将这个标志位置位，那么调用exec时会自动关闭对应的文件。可是为什么需要这个标志位呢？主要是出于安全的考虑。对于fork之后子进程执行exec这种场景，如果子进程可以操作父进程打开的文件，就会带来严重的安全隐患。一般来讲，调用exec的子进程时，因为它会另起炉灶，因此父进程打开的文件描述符也应该一并关闭，但事实上内核并没有主动这样做。试想如下场景，Webserver首先以root权限启动，打开只有拥有root权限才能打开的端口和日志等文件，再降到普通用户，fork出一些worker进程，在进程中进行解析脚本、写日志、输出结果等操作。由于子进程完全可以操作父进程打开的文件，因此子进程中的脚本只要继续操作这些文件描述符，就能越权操作root用户才能操作的文件。
为了解决这个问题，Linux引入了close on exec机制。设置了FD_CLOSEXEC标志位的文件，在子进程调用exec家族函数时会将相应的文件关闭。
而设置该标志位的方法有两种：

open时，带上O_CLOSEXEC标志位。
open时如果未设置，那就在后面调用fcntl函数的F_SETFD操作来设置。

建议使用第一种方法。原因是第二种方法在某些时序条件下并不那么绝对的安全。
考虑以下的场景：Thread 1还没来得及将FD_CLOSEXEC置位，由于Thread 2已经执行过fork，这时候fork出来的子进程就不会关闭相应的文件。尽管Thread1后来调用了fcntl的F_SETFD操作，但是为时已晚，文件已经泄露了。


多线程程序执行了fork，仅仅是为了示意，实际中并不鼓励这种做法。正相反，这种做法是十分危险的。多线程程序不应该调用fork来创建子进程。

前面提到，执行fork时，子进程会获取父进程所有文件描述符的副本，但是测试结果表明，父子进程共享了文件的很多属性。这到底是怎么回事？让我们深入内核一探究竟。
在内核的进程描述符task_struct结构体中，与打开文件相关的变量如下所示：
struct task_struct &#123;    ...    struct files_struct *files;    ...&#125;// 调用fork时，内核会在copy_files函数中处理拷贝父进程打开的文件的相关事宜：static int copy_files(unsigned long clone_flags, struct task_struct *tsk)&#123;    struct files_struct *oldf, *newf;    int error = 0;    oldf = current-&gt;files;    if (!oldf)        goto out; /*创建线程和vfork，都不用复制父进程的文件描述符，增加引用计数即可*/    if (clone_flags &amp; CLONE_FILES) &#123;        atomic_inc(&amp;oldf-&gt;count);        goto out;    &#125;    /*对于fork而言，需要复制父进程的文件描述符*/    newf = dup_fd(oldf, &amp;error);    if (!newf)        goto out;    tsk-&gt;files = newf;    error = 0;out:    return error;&#125;

CLONE_FILES标志位用来控制是否共享父进程的文件描述符。如果该标志位置位，则表示不必费劲复制一份父进程的文件描述符了，增加引用计数，直接共用一份就可以了。对于vfork函数和创建线程的pthread_create函数来说都是如此。但是fork函数却不同，调用fork函数时，该标志位为0，表示需要为子进程拷贝一份父进程的文件描述符。文件描述符的拷贝是通过内核的dup_fd函数来完成的。
struct files_struct *dup_fd(struct files_struct *oldf, int *errorp)&#123;    struct files_struct *newf;    struct file **old_fds, **new_fds;    int open_files, size, i;    struct fdtable *old_fdt, *new_fdt;    *errorp = -ENOMEM;    newf = kmem_cache_alloc(files_cachep, GFP_KERNEL);    if (!newf)        goto out;

dup_fd函数首先会给子进程分配一个file_struct结构体，然后做一些赋值操作。这个结构体是进程描述符中与打开文件相关的数据结构，每一个打开的文件都会记录在该结构体中。其定义代码如下：
struct files_struct &#123;    atomic_t count;    struct fdtable __rcu *fdt;    struct fdtable fdtab;    spinlock_t file_lock ____cacheline_aligned_in_smp;    int next_fd;    struct embedded_fd_set close_on_exec_init;    struct embedded_fd_set open_fds_init;    struct file __rcu * fd_array[NR_OPEN_DEFAULT];&#125;;struct fdtable&#123;    unsigned int max_fds;    struct file __rcu **fd;      /* current fd array */    fd_set *close_on_exec;    fd_set *open_fds;    struct rcu_head rcu;    struct fdtable *next;&#125;;struct embedded_fd_set &#123;    unsigned long fds_bits[1];&#125;;

初看之下struct fdtable的内容与struct files_struct的内容有颇多重复之处，包括close_on_exec文件描述符位图、打开文件描述符位图及file指针数组等，但事实上并非如此。struct files_struct中的成员是相应数据结构的实例，而struct fdtable中的成员是相应的指针。
Linux系统假设大多数的进程打开的文件不会太多。于是Linux选择了一个long类型的位数（32位系统下为32位，64位系统下为64位）作为经验值。以64位系统为例，file_struct结构体自带了可以容纳64个struct file类型指针的数组fd_array，也自带了两个大小为64的位图，其中open_fds_init位图用于记录文件的打开情况，close_on_exec_init位图用于记录文件描述符的FD_CLOSEXCE标志位是否置位。只要进程打开的文件个数小于64，file_struct结构体自带的指针数组和两个位图就足以满足需要。因此在分配了file_struct结构体后，内核会初始化file_struct自带的fdtable，代码如下所示：
atomic_set(&amp;newf-&gt;count, 1);spin_lock_init(&amp;newf-&gt;file_lock);newf-&gt;next_fd = 0;new_fdt = &amp;newf-&gt;fdtab;new_fdt-&gt;max_fds = NR_OPEN_DEFAULT;new_fdt-&gt;close_on_exec = (fd_set *)&amp;newf-&gt;close_on_exec_init;new_fdt-&gt;open_fds = (fd_set *)&amp;newf-&gt;open_fds_init;new_fdt-&gt;fd = &amp;newf-&gt;fd_array[0];new_fdt-&gt;next = NULL;

初始化之后，子进程的file_struct的情况如图所示。注意，此时file_struct结构体中的fdt指针并未指向file_struct自带的struct fdtable类型的fdtab变量。原因很简单，因为此时内核还没有检查父进程打开文件的个数，因此并不确定自带的结构体能否满足需要。

接下来，内核会检查父进程打开文件的个数。如果父进程打开的文件超过了64个，struct files_struct中自带的数组和位图就不能满足需要了。这种情况下内核会分配一个新的struct fdtable，代妈如下：
 spin_lock(&amp;oldf-&gt;file_lock); old_fdt = files_fdtable(oldf); open_files = count_open_files(old_fdt);/*如果父进程打开文件的个数超过NR_OPEN_DEFAULT*/ while (unlikely(open_files &gt; new_fdt-&gt;max_fds)) &#123;     spin_unlock(&amp;oldf-&gt;file_lock);  /* 如果不是自带的fdtable而是曾经分配的fdtable，则需要先释放*/     if (new_fdt != &amp;newf-&gt;fdtab)     __free_fdtable(new_fdt);    /*创建新的fdtable*/     new_fdt = alloc_fdtable(open_files - 1);     if (!new_fdt) &#123;     *errorp = -ENOMEM;     goto out_release;     &#125;     /*如果超出了系统限制，则返回EMFILE*/     if (unlikely(new_fdt-&gt;max_fds &lt; open_files)) &#123;     __free_fdtable(new_fdt);     *errorp = -EMFILE;     goto out_release;     &#125;     spin_lock(&amp;oldf-&gt;file_lock);     old_fdt = files_fdtable(oldf);     open_files = count_open_files(old_fdt); &#125;

alloc_fdtable所做的事情，不过是分配fdtable结构体本身，以及分配一个指针数组和两个位图。分配之前会根据父进程打开文件的数目，计算出一个合理的值nr，以确保分配的数组和位图能够满足需要。

无论是使用file_struct结构体自带的fdtable，还是使用alloc_fdtable分配的fdtable，接下来要做的事情都一样，即将父进程的两个位图信息和打开文件的struct file类型指针拷贝到子进程的对应数据结构中，代码如下：
    old_fds = old_fdt-&gt;fd;  /*父进程的struct file 指针数组*/    new_fds = new_fdt-&gt;fd;  /*子进程的struct file 指针数组*/    /* 拷贝打开文件位图 */    memcpy(new_fdt-&gt;open_fds-&gt;fds_bits,old_fdt-&gt;open_fds-&gt;fds_bits, open_files/8);    /* 拷贝 close_on_exec位图 */    memcpy(new_fdt-&gt;close_on_exec-&gt;fds_bits,old_fdt-&gt;close_on_exec-&gt;fds_bits, open_files/8);    for (i = open_files; i != 0; i--)     &#123;            struct file *f = *old_fds++;        if (f) &#123;                    get_file(f); /* f对应的文件的引用计数加1 */            &#125; else &#123;                    FD_CLR(open_files - i, new_fdt-&gt;open_fds);            &#125;/* 子进程的struct file类型指针，*指向和父进程相同的struct file 结构体*/            rcu_assign_pointer(*new_fds++, f);       &#125;    spin_unlock(&amp;oldf-&gt;file_lock);/* compute the remainder to be cleared */    size = (new_fdt-&gt;max_fds - open_files) * sizeof(struct file *);    /*将尚未分配到的struct file结构的指针清零*/    memset(new_fds, 0, size);/*将尚未分配到的位图区域清零*/    if (new_fdt-&gt;max_fds &gt; open_files) &#123;            int left = (new_fdt-&gt;max_fds-open_files)/8;            int start = open_files / (8 * sizeof(unsigned long));            memset(&amp;new_fdt-&gt;open_fds-&gt;fds_bits[start], 0, left);            memset(&amp;new_fdt-&gt;close_on_exec-&gt;fds_bits[start], 0, left);    &#125;    rcu_assign_pointer(newf-&gt;fdt, new_fdt);    return newf;out_release:    kmem_cache_free(files_cachep, newf);out:    return NULL;&#125;


procfs的&#x2F;proc&#x2F;PID&#x2F;status中的FDSize，记录了当前fdtable的大小：
$ cat /proc/1/status FDSize: 128

当然了，FDSize记录的是目前fdtable能容纳的struct file指针，而不是已经打开的文件个数，已经打开的文件记录在&#x2F;proc&#x2F;PID&#x2F;fd中。通过对上述流程的梳理，不难看出，父子进程之间拷贝的是struct file的指针，而不是struct file的实例，父子进程的struct file类型指针，都指向同一个struct file实例。fork之后，父子进程的文件描述符关系如图所示。

下面来看看struct file成员变量：
struct file&#123;    ...    unsigned int    f_flags    fmode_t         f_mode    loff_t          f_pos;/*文件位置指针的当前值，即文件偏移量*/    ...&#125;

看到此处，就不难理解父子进程是如何共享文件偏移量的了，那是因为父子进程的指针都指向了同一个struct file结构体。
vfork在早期的实现中，fork没有实现写时拷贝机制，而是直接对父进程的数据段、堆和栈进行完全拷贝，效率十分低下。很多程序在fork一个子进程后，会紧接着执行exec家族函数，这更是一种浪费。所以BSD引入了vfork。既然fork之后会执行exec函数，拷贝父进程的内存数据就变成了一种无意义的行为，所以引入的vfork压根就不会拷贝父进程的内存数据，而是直接共享。再后来Linux引入了写时拷贝的机制，其效率提高了很多，这样一来，vfork其实就可以退出历史舞台了。除了一些需要将性能优化到极致的场景，大部分情况下不需要再使用vfork函数了。
vfork会创建一个子进程，该子进程会共享父进程的内存数据，而且系统将保证子进程先于父进程获得调度。子进程也会共享父进程的地址空间，而父进程将被一直挂起，直到子进程退出或执行exec。注意，vfork之后，子进程如果返回，则不要调用return，而应该使用_exit函数。如果使用return，就会出现诡异的错误。请看下面的示例代码：
#include &lt;stdio.h&gt;#include &lt;stdlib.h&gt;#include &lt;unistd.h&gt;int glob = 88 ;int main(void) &#123;    int var;    var = 88;    pid_t pid;    if ((pid = vfork()) &lt; 0) &#123;        printf(&quot;vfork error&quot;);        exit(-1);    &#125; else if (pid == 0) &#123; /* 子进程 */        var++;        glob++;        return 0;    &#125;    printf(&quot;pid=%d, glob=%d, var=%d\n&quot;,getpid(), glob, var);    return 0;&#125;

调用子进程，如果使用return返回，就意味着main函数返回了，因为栈是父子进程共享的，所以程序的函数栈发生了变化。main函数return之后，通常会调用exit系的函数，父进程收到子进程的exit之后，就会开始从vfork返回，但是这时整个main函数的栈都已经不复存在了，所以父进程压根无法执行。于是会返回一个诡异的栈地址，对于在某些内核版本中，进程会直接报栈错误然后退出，但是在某些内核版本中，有可能就会再次进出main，于是进入一个无限循环，直到vfork返回错误。笔者的Ubuntu版本就是后者。一般来说，vfork创建的子进程会执行exec，执行完exec后应该调用_exit返回。注意是_exit而不是exit。因为exit会导致父进程stdio缓冲区的冲刷和关闭。我们会在后面讲述exit和_exit的区别。

高版本内核修复了这个问题。

Daemon进程的创建daemon进程又被称为守护进程，一般来说它有以下两个特点：

生命周期很长，一旦启动，正常情况下不会终止，一直运行到系统退出。但凡事无绝对：daemon进程其实也是可以停止的，如很多daemon提供了stop命令，执行stop命令就可以终止daemon，或者通过发送信号将其杀死，又或者因为daemon进程代码存在bug而异常退出。这些退出一般都是由手工操作或因异常引发的。
在后台执行，并且不与任何控制终端相关联。即使daemon进程是从终端命令行启动的，终端相关的信号如SIGINT、SIGQUIT和SIGTSTP，以及关闭终端，都不会影响到daemon进程的继续执行。

习惯上daemon进程的名字通常以d结尾，如sshd、rsyslogd等。但这仅仅是习惯，并非一定要如此。如何使一个进程变成daemon进程，或者说编写daemon进程，需要遵循哪些规则或步骤呢？一般来讲，创建一个daemon进程的步骤被概括地称为double-fork magic。细细说来，需要以下步骤：
（1）执行fork（）函数，父进程退出，子进程继续执行这一步。
原因有二：

父进程有可能是进程组的组长（在命令行启动的情况下），从而不能够执行后面要执行的setsid函数，子进程继承了父进程的进程组ID，并且拥有自己的进程ID，一定不会是进程组的组长，所以子进程一定可以执行后面要执行的setsid函数。
如果daemon是从终端命令行启动的，那么父进程退出会被shell检测到，shell会显示shell提示符，让子进程在后台执行。

（2）子进程执行如下三个步骤，以摆脱与环境的关系。

修改进程的当前目录为根目录（&#x2F;）。这样做是有原因的，因为daemon一直在运行，如果当前工作路径上包含有根文件系统以外的其他文件系统，那么这些文件系统将无法卸载。因此，常规是将当前工作目录切换成根目录，当然也可以是其他目录，只要确保该目录所在的文件系统不会被卸载即可。
chdir(&quot;/&quot;)

调用setsid函数。这个函数的目的是切断与控制终端的所有关系，并且创建一个新的会话。这一步比较关键，因为这一步确保了子进程不再归属于控制终端所关联的会话。因此无论终端是否发送SIGINT、SIGQUIT或SIGTSTP信号，也无论终端是否断开，都与要创建的daemon进程无关，不会影响到daemon进程的继续执行。

设置文件模式创建掩码为0。这一步的目的是让daemon进程创建文件的权限属性与shell脱离关系。因为默认情况下，进程的umask来源于父进程shell的umask。如果不执行umask（0），那么父进程shell的umask就会影响到daemon进程的umask。如果用户改变了shell的umask，那么也就相当于改变了daemon的umask，就会造成daemon进程每次执行的umask信息可能会不一致。
umask(0)

（3）再次执行fork，父进程退出，子进程继续。
执行完前面两步之后，可以说已经比较圆满了：新建会话，进程是会话的首进程，也是进程组的首进程。进程ID、进程组ID和会话ID，三者的值相同，进程和终端无关联。那么这里为何还要再执行一次fork函数呢？原因是，daemon进程有可能会打开一个终端设备，即daemon进程可能会根据需要，执行类似如下的代码：
int fd = open(&quot;/dev/console&quot;, O_RDWR);

这个打开的终端设备是否会成为daemon进程的控制终端，取决于两点：

daemon进程是不是会话的首进程。
系统实现。（BSD风格的实现不会成为daemon进程的控制终端，但是POSIX标准说这由具体实现来决定）。

既然如此，为了确保万无一失，只有确保daemon进程不是会话的首进程，才能保证打开的终端设备不会自动成为控制终端。因此，不得不执行第二次fork，fork之后，父进程退出，子进程继续。这时，子进程不再是会话的首进程，也不是进程组的首进程了。
（4）关闭标准输入（stdin）、标准输出（stdout）和标准错误（stderr）。
因为文件描述符0、1和2指向的就是控制终端。daemon进程已经不再与任意控制终端相关联，因此这三者都没有意义。一般来讲，关闭了之后，会打开&#x2F;dev&#x2F;null，并执行dup2函数，将0、1和2重定向到&#x2F;dev&#x2F;null。这个重定向是有意义的，防止了后面的程序在文件描述符0、1和2上执行I&#x2F;O库函数而导致报错。
至此，即完成了daemon进程的创建，进程可以开始自己真正的工作了。
上述步骤比较繁琐，对于C语言而言，glibc提供了daemon函数，从而帮我们将程序转化成daemon进程。
#include &lt;unistd.h&gt;/**  @nochdir: 用来控制是否将当前工作目录切换到根目录。*           0：将当前工作目录切换到/。*           1：保持当前工作目录不变。*  @noclose: 用来控制是否将标准输入、标准输出和标准错误重定向到/dev/null。*           0：将标准输入、标准输出和标准错误重定向到/dev/null。*           1：保持标准输入、标准输出和标准错误不变。*/int daemon(int nochdir, int noclose);// 一般情况下，这两个入参都要为0。ret = daemon(0,0)/** 成功时，daemon函数返回0；失败时，返回-1，并置errno。* 因为daemon函数内部会调用fork函数和setsid函数，所以出错时errno可以查看fork函数和setsid函数的出错情形。* glibc的daemon函数做的事情，和前面讨论的大体一致，但是做得并不彻底，没有执行第二次的fork。*/#include &lt;unistd.h&gt;int main(int argc,char *argv[])&#123; 	if (daemon(0, 0)) &#123;//调用glibc库函数daemon,创建daemon守护进程        perror(&quot;daemon&quot;);        return -1;   	&#125;    // 子进程内容&#125;int daemon( int nochdir, int noclose )&#123;   pid_t pid;   if ( !nochdir &amp;&amp; chdir(&quot;/&quot;) != 0 )   //如果nochdir=0,那么改变到&quot;/&quot;根目录       return -1;   if ( !noclose )                      //如果没有noclose=0，那么开始输入,输出以及错误输出重定向到/dev/null    &#123;     int fd = open(&quot;/dev/null&quot;, O_RDWR);//打开神奇的黑洞文件.     if ( fd &lt; 0 )      return -1;//每个进程都拥有自己fds文件描述符表，//fdt-&gt;fd[0],fdt-&gt;fd[1],fdt-&gt;fd[2],//表中fd[0],fd[1],和fd[2]文件句柄位置对应的fops文件操作函数集,分别与标准输入,标准输出,标准错误输出相关联//所以用户应用程序调用open函数打开文件时,默认都是以3索引为开始句柄,也就是fd[3]，故当前open返回的文件句柄最小值为3//dup2(unsigned int oldfd, unsigned int newfd)系统调用就是用oldfd的fops操作文件集file,复制到newfd所在处//即：fdt-&gt;fd[newfd] = fdt-&gt;fd[oldfd];     if ( dup2( fd, 0 ) &lt; 0 || //使用字符设备/dev/null的fops函数操作集,替换0句柄对应的文件操作集.     dup2( fd, 1 ) &lt; 0 ||      //使用字符设备/dev/null的fops函数操作集,替换1句柄对应的文件操作集.          dup2( fd, 2 ) &lt; 0 )  //使用字符设备/dev/null的fops函数操作集,替换2句柄对应的文件操作集.     &#123;       close(fd);      return -1;     &#125; //如果替换成功,那么键盘的任何操作将不会对该进程产生任何影响,因为0,1,2句柄所在处的fops文件操作集已经都变成了, //被重定向为&quot;/dev/null&quot;空洞设备的fops.所以对0,1,2句柄的读写操作,也就是在对/dev/null设备作读写操作.     close(fd); //关闭打开的/dev/null  &#125;   pid = fork();//创建子进程.   if (pid &lt; 0)    return -1;   if (pid &gt; 0)    _exit(0);  //返回执行的是父进程,那么父进程退出,让子进程变成真正的孤儿进程.               //ok,我们期望的daemon子进程执行到这里了.   if ( setsid() &lt;