简介项目地址：https://github.com/jelasin/LibCoroutine
使用C开发的一个协程库，支持协程同步，动态添加，通过调度器进行协程调度。
整体架构等待队列这里只画了一个，实际上每个条件变量都有一个自己的等待队列。

数据结构co_types.h#ifndef __CO_TYPES_H__#define __CO_TYPES_H__#include &lt;ucontext.h&gt;typedef enum &#123;    COROUTINE_READY,    COROUTINE_RUNNING,    COROUTINE_SUSPENDED,    COROUTINE_SIGNALER,    COROUTINE_WAITING,    COROUTINE_FINISHED&#125; CoroutineState;typedef enum &#123;    COROUTINE_OK,    COROUTINE_NO,&#125; ConditionState;typedef struct coroutine_t &#123;    ucontext_t context;    char *stack;    size_t stack_size;    CoroutineState state;    void (*func)(void *);    void *arg;    struct coroutine_t *next;&#125; coroutine_t;typedef struct &#123;    ucontext_t main_context; // the context of the main thread    coroutine_t *current;   // the current coroutine    coroutine_t *ready_queue; // the ready queue of coroutines&#125; scheduler_t; typedef struct coroutine_cond_t &#123;    coroutine_t *wait_queue;    ConditionState state;&#125; coroutine_cond_t;#endif

coroutine.h#ifndef __COROUTINE_H__#define __COROUTINE_H__#include &quot;co_control.h&quot;#include &quot;co_scheduler.h&quot;inline void coroutine_set_memory_hook(void* (*alloc)(size_t size), void (*release)(void* ptr))&#123;    coroutine_set_memory_alloc_ct(alloc);    coroutine_set_memory_free_ct(release);    coroutine_set_memory_alloc_sh(alloc);    coroutine_set_memory_free_sh(release);&#125;#endif /* __COROUTINE_H__ */

调度器实现co_scehduler.h#ifndef __CO_SCHEDULER_H__#define __CO_SCHEDULER_H__#include &quot;co_types.h&quot;extern scheduler_t *coroutine_scheduler_create();extern void coroutine_scheduler_destroy(scheduler_t *sched);extern void coroutine_scheduler_run(scheduler_t *sched);// 设置内存分配函数extern void coroutine_set_memory_alloc_sh(void* (*alloc)(size_t size));// 设置内存释放函数extern void coroutine_set_memory_free_sh(void (*release)(void* ptr));#endif /* __CO_SCHEDULER_H__ */

coroutine_scheduler_create// 调度器初始化scheduler_t *coroutine_scheduler_create() &#123;    scheduler_t *sched = (scheduler_t *)malloc(sizeof(scheduler_t));    if (NULL == sched)     &#123;        return NULL;    &#125;    sched-&gt;current = NULL;    sched-&gt;ready_queue = NULL;    return sched;&#125;

coroutine_scheduler_destroy// 释放资源void coroutine_scheduler_destroy(scheduler_t *sched) &#123;    if (NULL == sched)    &#123;        return;    &#125;    free(sched);    sched = NULL;&#125;

coroutine_scheduler_run// 启动调度器void coroutine_scheduler_run(scheduler_t *sched)&#123;    if (getcontext(&amp;sched-&gt;main_context) == -1)     &#123;        return;    &#125;    while (sched-&gt;ready_queue != NULL)     &#123;        // 从等待队列中找到一个就绪态协程        coroutine_t *co = sched-&gt;ready_queue;        if (COROUTINE_READY == co-&gt;state)        &#123;            // 如果是就绪态，将其置为RUNNING，并从就绪队列中移除，添加到current.            sched-&gt;ready_queue = co-&gt;next;            co-&gt;state = COROUTINE_RUNNING;            sched-&gt;current = co;        &#125;        else        &#123;            // 如果当前协程不是就绪状态，跳过它            static int count = 0; // 防止死循环            if (++count &gt; 100)             &#123;                return;            &#125;            coroutine_t *tail = sched-&gt;ready_queue; // 找到队列尾部            while (NULL != tail-&gt;next)            &#123;                tail = tail-&gt;next; // 遍历到队列的最后一个协程            &#125;            tail-&gt;next = co; // 将当前协程重新加入到队列尾部            co-&gt;next = NULL; // 确保当前协程的next指针为NULL            sched-&gt;ready_queue = sched-&gt;ready_queue-&gt;next; // 移出队头            continue;        &#125;        // 保存当前调度器上下文，切换至协程        swapcontext(&amp;sched-&gt;main_context, &amp;co-&gt;context);        // 协程执行完毕后的清理        if (COROUTINE_FINISHED == co-&gt;state)         &#123;            free(co-&gt;stack);            co-&gt;stack = NULL;            free(co);            co = NULL;        &#125;        else if (COROUTINE_SUSPENDED == co-&gt;state || COROUTINE_SIGNALER == co-&gt;state)        &#123;            // 这里吧他们挂到就绪队列尾部，            // 一般来说，当我们再次带用到 COROUTINE_SIGNALER 协程时，已经有wait的协程了。            // 如果没有在wait的协程，我们在co_signal时做了处理。            if (sched-&gt;ready_queue == NULL)            &#123;                sched-&gt;ready_queue = co;            &#125;            else            &#123;                coroutine_t *tail = sched-&gt;ready_queue;                while (NULL != tail-&gt;next)                &#123;                    tail = tail-&gt;next;                &#125;                tail-&gt;next = co;                co-&gt;state = COROUTINE_READY; // 恢复为就绪状态            &#125;            co-&gt;next = NULL;        &#125;    &#125;&#125;

协程控制实现co_control.h#ifndef __CO_CONTROL_H__#define __CO_CONTROL_H__#include &quot;co_types.h&quot;extern coroutine_t *coroutine_create(scheduler_t *sched, void (*func)(void *), void *arg, size_t stack_size);extern void coroutine_yield(scheduler_t *sched);extern void coroutine_cond_init(coroutine_cond_t *cond);extern int coroutine_cond_wait(scheduler_t *sched, coroutine_cond_t *cond);extern int coroutine_cond_signal(scheduler_t *sched, coroutine_cond_t *cond);// 设置内存分配函数extern void coroutine_set_memory_alloc_ct(void* (*alloc)(size_t size));// 设置内存释放函数extern void coroutine_set_memory_free_ct(void (*release)(void* ptr));#endif /* __CO_CONTROL_H__ */

coroutine_createcoroutine_t *coroutine_create(scheduler_t *sched, void (*func)(void *), void *arg, size_t stack_size) &#123;    coroutine_t *co = (coroutine_t *)malloc(sizeof(coroutine_t));    if (NULL == co)     &#123;        return NULL;    &#125;	// 申请协程栈    co-&gt;stack = (char *)malloc(stack_size);    if (NULL == co-&gt;stack)    &#123;        free(co);        co = NULL;        return NULL;    &#125;	// 获取制作协程上下文    if (getcontext(&amp;co-&gt;context) &lt; 0)     &#123;        free(co-&gt;stack);        co-&gt;stack = NULL;        free(co);        co = NULL;        return NULL;    &#125;    co-&gt;context.uc_stack.ss_sp = co-&gt;stack;    co-&gt;context.uc_stack.ss_size = stack_size;    co-&gt;context.uc_link = &amp;sched-&gt;main_context; // 关联主调度器上下文    co-&gt;func = func;    co-&gt;arg = arg;    co-&gt;state = COROUTINE_READY;    co-&gt;stack_size = stack_size;    co-&gt;next = NULL;    // 加入就绪队列尾部    if (NULL == sched-&gt;ready_queue)     &#123;        sched-&gt;ready_queue = co;    &#125;    else    &#123;        coroutine_t *tail = sched-&gt;ready_queue;        while (NULL != tail-&gt;next)        &#123;            tail = tail-&gt;next;        &#125;        tail-&gt;next = co;    &#125;	// 制作协程上下文    makecontext(&amp;co-&gt;context, (void (*)())coroutine_entry, 1, co);    return co;&#125;// 协程入口函数static void coroutine_entry(coroutine_t *co) &#123;    co-&gt;func(co-&gt;arg);          // 执行用户函数    co-&gt;state = COROUTINE_FINISHED; // 协程结束&#125;

coroutine_yield// 协程让出CPUvoid coroutine_yield(scheduler_t *sched) &#123;    // 获取当前正在执行的协程    coroutine_t *current = sched-&gt;current;    if (NULL == current)    &#123;        return;    &#125;    // 将当前协程移到就绪队列尾部    if (NULL != sched-&gt;ready_queue)    &#123;        coroutine_t *tail = sched-&gt;ready_queue;        while (NULL != tail-&gt;next)         &#123;            tail = tail-&gt;next;        &#125;        tail-&gt;next = current;    &#125;    else    &#123;        sched-&gt;ready_queue = current;    &#125;    current-&gt;next = NULL;    // 协程状态置为挂起状态    current-&gt;state = COROUTINE_SUSPENDED;    // 保存当前上下文，切换回主调度器，由调度器选择下一个协程    swapcontext(&amp;current-&gt;context, &amp;sched-&gt;main_context);&#125;

coroutine_cond_initvoid coroutine_cond_init(coroutine_cond_t *cond)&#123;    if (NULL == cond)    &#123;        return;    &#125;    cond-&gt;wait_queue = NULL;    cond-&gt;state = COROUTINE_NO; // 初始化为NO&#125;

coroutine_cond_waitint coroutine_cond_wait(scheduler_t *sched, coroutine_cond_t *cond)&#123;    coroutine_t *co = sched-&gt;current;    if (NULL == co || NULL == cond || NULL == sched)    &#123;        return -1; // 参数错误    &#125;    // 条件变量状态为OK, 说明并未先执行本协程, 条件已经满足, 直接返回    if (cond-&gt;state == COROUTINE_OK)    &#123;        return 0;    &#125;    // 将当前协程加入到条件变量的等待列表    if (NULL == cond-&gt;wait_queue)    &#123;        cond-&gt;wait_queue = co; // 第一个等待的协程    &#125;    else    &#123;        coroutine_t *tail = cond-&gt;wait_queue;        while (NULL != tail-&gt;next)         &#123;            tail = tail-&gt;next;        &#125;        tail-&gt;next = co; // 加入到等待列表尾部    &#125;    co-&gt;next = NULL; // 确保next指针为NULL    co-&gt;state = COROUTINE_WAITING; // 等待状态	// 保存当前协程上下文，返回主调度器    swapcontext(&amp;co-&gt;context, &amp;sched-&gt;main_context);    /*     * 当协程被唤醒后，会从这里继续执行。     * 协程从sched-&gt;ready_queue中移除, 加入了cond-&gt;wait_queue中,      * 只有可能被coroutine_cond_signal唤醒, 且条件已经满足.     */    cond-&gt;state = COROUTINE_NO; // 设置条件变量状态为NO, 表示状态已经被消费    return 0;&#125;

coroutine_cond_signalint coroutine_cond_signal(scheduler_t *sched, coroutine_cond_t *cond)&#123;    coroutine_t *co = sched-&gt;current; // 当前协程    if (NULL == co || NULL == cond || NULL == sched)    &#123;        return -1;    &#125;    while (NULL == cond-&gt;wait_queue)    &#123;        // 这里一般来说只会进来一次，而且这种情况不应该出现。        // 这里属于先调用了signal，出现这种情况只可能是调度出现了问题。        cond-&gt;state = COROUTINE_NO; // 没有等待的协程, 设置为而NO        co-&gt;state = COROUTINE_SIGNALER; // 当前协程是信号发送者, 便于后续调度器处理        swapcontext(&amp;co-&gt;context, &amp;sched-&gt;main_context); // 保存上下文，切回主调度器    &#125;    cond-&gt;state = COROUTINE_OK; // 设置条件变量状态为OK, 表示条件已经满足        coroutine_t *waiting_co = cond-&gt;wait_queue; // 取出第一个等待的协程    cond-&gt;wait_queue = waiting_co-&gt;next; // 移除等待列表中的第一个协程    // 将waiting_co从等待列表中移除, 加入到就绪队列头部    waiting_co-&gt;next = sched-&gt;ready_queue;    sched-&gt;ready_queue = waiting_co;    waiting_co-&gt;state = COROUTINE_READY; // 设置状态为就绪    co-&gt;state = COROUTINE_SIGNALER; // 当前协程是信号发送者, 便于后续调度器处理    // 切换回主调度器。    swapcontext(&amp;co-&gt;context, &amp;sched-&gt;main_context);        return 0;&#125;

示例#include &quot;coroutine.h&quot;#include &lt;stdio.h&gt;struct arg&#123;    int num;    scheduler_t *sched;    coroutine_cond_t *cond;&#125;;void producer(void *arg)&#123;    struct arg *p = (struct arg *)arg;    scheduler_t *sched = p-&gt;sched;    for (int i = 0; i &lt; 3; i++)    &#123;        printf(&quot;Producing %d %d\n&quot;, i, ++p-&gt;num);        coroutine_cond_wait(sched, p-&gt;cond); // 等待条件变量    &#125;&#125;void consumer(void *arg)&#123;    struct arg *p = (struct arg *)arg;    scheduler_t *sched = p-&gt;sched;    for (int i = 0; i &lt; 3; i++)     &#123;        printf(&quot;Consuming %d %d\n&quot;, i, --p-&gt;num);        coroutine_cond_signal(sched, p-&gt;cond); // 通知生产者    &#125;&#125;void other(void *arg)&#123;    struct arg *p = (struct arg *)arg;    scheduler_t *sched = p-&gt;sched;    for (int i = 0; i &lt; 3; i++)     &#123;        printf(&quot;other     %d\n&quot;, i);        coroutine_yield(sched); // 切换到其他协程    &#125;&#125;int main() &#123;    struct arg arg;    scheduler_t *sched = coroutine_scheduler_create();    arg.sched = sched;    arg.num = 10;    coroutine_cond_t cond;    coroutine_cond_init(&amp;cond); // 初始化条件变量    arg.cond = &amp;cond; // 传递条件变量给协程    coroutine_create(sched, producer, &amp;arg, 1 &lt;&lt; 20); // 1MB栈    coroutine_create(sched, consumer, &amp;arg, 1 &lt;&lt; 20);    coroutine_create(sched, other, &amp;arg, 1 &lt;&lt; 20);    coroutine_scheduler_run(sched);    coroutine_scheduler_destroy(sched);    return 0;&#125;

