seqlist.c
#include &quot;seqlist.h&quot;seqlist_t *create_empty_seqlist()&#123;    seqlist_t * l = (seqlist_t *)malloc(sizeof(seqlist_t));    if (NULL == l)    &#123;        perror(RED &quot;[-] malloc error when create_empty_seqlist&quot; NONE);        return NULL;    &#125;    memset(l, &#x27;\x00&#x27;, sizeof(seqlist_t));    l-&gt;n = 0;    return l;&#125;bool is_full_seqlist(seqlist_t *l)&#123;    return l-&gt;n &gt;= MAX ? true : false;&#125;void insert_data_seqlist(seqlist_t *l, datatype_t data)&#123;    if (is_full_seqlist(l))     &#123;        printf(RED &quot;[*]The list is full, cannot insert data.\n&quot; NONE);        return;    &#125;        l-&gt;buf[l-&gt;n] = data;    l-&gt;n++;    return;&#125;void printf_data_seqlist(seqlist_t *l)&#123;    for (int i = 0; i &lt; l-&gt;n; i++)    &#123;        printf(&quot;Name: %s, ID: %d, Age: %d\n&quot;, l-&gt;buf[i].name, l-&gt;buf[i].id, l-&gt;buf[i].age);    &#125;    return;&#125;void destroy_seqlist(seqlist_t *l)&#123;    free(l);    l = NULL;    return;&#125;bool is_empty_seqlist(seqlist_t *l)&#123;    return l-&gt;n == 0 ? true : false;&#125;bool is_equal(datatype_t a, datatype_t b)&#123;    if (a.age == b.age &amp;&amp; a.id == b.id &amp;&amp; !strcmp(a.name, b.name))    &#123;        return true;    &#125;    else    &#123;        return false;    &#125;&#125;int delete_data_seqlist(seqlist_t *l, datatype_t data)&#123;    if (is_empty_seqlist(l))     &#123;        return -1;    &#125;    int i = 0, j = 0;		// i用于遍历整个表，j用于标记被删除或已经移动的data。    for (i = 0; i &lt; l-&gt;n; i++)     &#123;        if (!is_equal(l-&gt;buf[i], data))         &#123;            l-&gt;buf[j++] = l-&gt;buf[i];        &#125;    &#125;    // 遍历完成，j刚好是应该更新的n。    l-&gt;n = j;	// 没找到要删除的元素。    if (i == j)    &#123;        return -2;    &#125;    &#125;int find_data_seqlist(seqlist_t *l, datatype_t data)&#123;    for (int i = 0; i &lt; l-&gt;n; i++)     &#123;        if (is_equal(l-&gt;buf[i], data))         &#123;            return i;        &#125;    &#125;    return -1;&#125;int replace_data_seqlist(seqlist_t *l, datatype_t old, datatype_t new)&#123;    while (-1 != find_data_seqlist(l, old))    &#123;        l-&gt;buf[find_data_seqlist(l, old)] = new;    &#125;    return 0;&#125;

