#include &quot;seqlist.h&quot;int test()&#123;    seqlist_t *list = create_empty_seqlist();    if (NULL == list)    &#123;        perror(RED &quot;[-]Failed to create seqlist&quot; NONE);        return 0;    &#125;    printf(&quot;[1] is_empty ==&gt; %s \n&quot;, is_empty_seqlist(list) ? &quot;true&quot; : &quot;false&quot;);        datatype_t data_1 = &#123; .age = 25, .id = 1, .name = &quot;John Doe&quot; &#125;;    datatype_t data_2 = &#123; .age = 26, .id = 2, .name = &quot;Trump&quot; &#125;;    for (size_t i = 0; i &lt; 5; i++)    &#123;        insert_data_seqlist(list, data_1);        insert_data_seqlist(list, data_2);    &#125;    printf(&quot;[2] printf_data_seqlist\n&quot;);    printf_data_seqlist(list);    printf(&quot;[3] delete data_2\n&quot;);    if(0 &gt; delete_data_seqlist(list, data_2))    &#123;        perror(RED &quot;[-] Failed to delete data from seqlist, seqlist is empty or data is not exist&quot; NONE);    &#125;    printf(&quot;[4] printf_data_seqlist\n&quot;);    printf_data_seqlist(list);        replace_data_seqlist(list, data_1, (datatype_t)&#123; .age = 30, .id = 3, .name = &quot;Jane Doe&quot; &#125;);    printf(&quot;[5] After replacement\n&quot;);    printf_data_seqlist(list);    printf(&quot;[6] destroy_seqlist\n&quot;);    destroy_seqlist(list);    return 0;&#125;int main(int argc, char const *argv[])&#123;    return test();&#125;

单链表单链表(Singly linked list)。我写的这种是带有头节点的单链表，并且头节点不存储数据，留有uint n用来记录链表长度。但是实现的时候却没怎麼用到uint n，而是按照不知道链表长度的方式来写。
