#ifndef __SLIST_H__#define __SLIST_H__#include&lt;stdio.h&gt;#include&lt;stdlib.h&gt;#include&lt;string.h&gt;#include&lt;stdbool.h&gt;#include&lt;stdint.h&gt;#define RED &quot;\033[31m&quot;#define NONE &quot;\033[0m&quot;typedef int datatype_t;typedef struct slist_node&#123;    datatype_t data;    struct slist_node * next;&#125; slist_node;typedef struct slist_head&#123;    uint32_t n;    slist_node *next;&#125; slist_head;extern slist_head* create_empyt_slist();extern int insert_head_slist(slist_head* head, datatype_t value);extern void print_slist(const slist_head* head);extern int insert_tail_slist(slist_head* head, datatype_t value);extern int insert_order_slist(slist_head* head, datatype_t value);extern void delete_node_slist(slist_head* head, datatype_t value);extern void destyroy_slist(slist_head* head);extern bool is_empty_slist(slist_head* head);extern uint32_t num_of_node_slist(slist_head* head);extern slist_node* find_node_slist(const slist_head* head, datatype_t value);extern void reverse_node_slist(slist_head* head);#endif

SList.c
#include &quot;SList.h&quot;slist_head* create_empyt_slist()&#123;    slist_head * l = (slist_head*)malloc(sizeof(slist_head));    if (NULL == l)    &#123;        perror(&quot;Failed to allocate memory for slist_head&quot;);        return NULL;    &#125;    memset(l, 0, sizeof(slist_head));    l-&gt;n = 0;    l-&gt;next = NULL;    return l;&#125;int insert_head_slist(slist_head* head, datatype_t value)&#123;    slist_node* new_node = (slist_node*)malloc(sizeof(slist_node));    if (NULL == new_node)    &#123;        perror(&quot;Failed to allocate memory for new node&quot;);        return -1;    &#125;    new_node-&gt;data = value;        new_node-&gt;next = head-&gt;next;    head-&gt;next = new_node;    head-&gt;n++;    return 0;&#125;int insert_tail_slist(slist_head* head, datatype_t value)&#123;    slist_node* new_node = (slist_node*)malloc(sizeof(slist_node));    if (NULL == new_node)    &#123;        perror(&quot;Failed to allocate memory for new node&quot;);        return -1;    &#125;    new_node-&gt;data = value;    slist_node* temp = head-&gt;next;    if (NULL != temp)    &#123;        while(NULL != temp-&gt;next)        &#123;            temp = temp-&gt;next;        &#125;    &#125;    else // 只有首个元素会调用,放在else block    &#123;        head-&gt;next = new_node;        new_node-&gt;next = NULL;        head-&gt;n++;        return 0;    &#125;    temp-&gt;next = new_node;    new_node-&gt;next = NULL;    head-&gt;n++;    return 0;&#125;int insert_order_slist(slist_head* head, datatype_t value)&#123;    slist_node* new_node = (slist_node*)malloc(sizeof(slist_node));    if (NULL == new_node)    &#123;        perror(&quot;Failed to allocate memory for new node&quot;);        return -1;    &#125;    new_node-&gt;data = value;    slist_node* temp = head-&gt;next;    if (NULL != temp)    &#123;        while (NULL != temp-&gt;next &amp;&amp; temp-&gt;next-&gt;data &lt; value)        &#123;            temp = temp-&gt;next;        &#125;    &#125;    else  // 只有首个元素会调用,放在else block    &#123;        head-&gt;next = new_node;        new_node-&gt;next = NULL;        head-&gt;n++;        return 0;    &#125;        new_node-&gt;next = temp-&gt;next;    temp-&gt;next = new_node;    head-&gt;n++;    return 0;&#125;slist_node* find_node_slist(const slist_head* head, const datatype_t value)&#123;    slist_node* current = head-&gt;next;    if (NULL != current)    &#123;            while (value != current-&gt;data)         &#123;            if (NULL != current-&gt;next)            &#123;                current = current-&gt;next;            &#125;            else            &#123;                return NULL;            &#125;        &#125;    &#125;    return current;&#125;void delete_node_slist(slist_head* head, datatype_t value)&#123;    while (NULL != find_node_slist(head, value))    &#123;        slist_node * p = head-&gt;next;        slist_node * q = NULL;        if (NULL != p)        &#123;            while (p-&gt;data != value)            &#123;                if (NULL != p-&gt;next)                &#123;                    q = p;                    p = p-&gt;next;                &#125;                else                &#123;                    return;                &#125;            &#125;            // 边界判断            if (NULL != q)            &#123;                q-&gt;next = p-&gt;next;                free(p);                p = NULL;                head-&gt;n--;            &#125;            else            &#123;                head-&gt;next = p-&gt;next;                free(p);                p = NULL;                head-&gt;n--;                if (head-&gt;n == 0)            	&#123;                	head-&gt;next = NULL;            	&#125;            &#125;        &#125;    &#125;&#125;void destyroy_slist(slist_head* head)&#123;    slist_node* current = head-&gt;next;    slist_node* p = NULL;    if (NULL != current)    &#123;        while (NULL != current-&gt;next)         &#123;            p = current;            current = current-&gt;next;            printf(&quot;%d &quot;, p-&gt;data);            free(p);            p = NULL;        &#125;        // current != NULL &amp;&amp; current-&gt;next == NULL        printf(&quot;%d \n&quot;, current-&gt;data);        free(current);        current = NULL;    &#125;    free(head);    head = NULL;&#125;bool is_empty_slist(slist_head* head)&#123;    return head-&gt;next == NULL ? true : false;&#125;uint32_t num_of_node_slist(slist_head* head)&#123;    return head-&gt;n;&#125;void reverse_node_slist(slist_head* head)&#123;    slist_node *prev = NULL;    slist_node *current = head-&gt;next;    slist_node *next = NULL;    // 只需要想办法把指针转过来即可,最简单的就是迭代法,记住前后位置,然后改变当前node的指针即可.    while (current != NULL)    &#123;        next = current-&gt;next;        current-&gt;next = prev;        prev = current;        current = next;    &#125;    // 最后head指向原tail.    head-&gt;next = prev;&#125;void print_slist(const slist_head* head)&#123;    const slist_node* current = head-&gt;next;    while (current != NULL) &#123;        printf(&quot;%d -&gt; &quot;, current-&gt;data);        current = current-&gt;next;    &#125;    printf(&quot;NULL\n&quot;);&#125;

