Dlist.c
#include &quot;DList.h&quot;dlist_head* create_dlist()&#123;    dlist_head * l = (dlist_head*)malloc(sizeof(dlist_head));    if (NULL == l)    &#123;        perror(&quot;Memory allocation failed&quot;);        return NULL;    &#125;    memset(l, &#x27;\x00&#x27;, sizeof(dlist_head));    return l;&#125;int insert_head_dlist(dlist_head* l, datatype_t data)&#123;        dlist_node* new_node = (dlist_node*)malloc(sizeof(dlist_node));    if (NULL == l)    &#123;        perror(&quot;Memory allocation failed&quot;);        return -1;    &#125;    new_node-&gt;data = data;        new_node-&gt;next = l-&gt;next;    new_node-&gt;prev = l;    l-&gt;next = new_node;    if (NULL != new_node-&gt;next)    &#123;        new_node-&gt;next-&gt;prev = new_node;    &#125;    return 0;&#125;int insert_tail_dlist(dlist_head* l, datatype_t data)&#123;    dlist_node* new_node = (dlist_node*)malloc(sizeof(dlist_node));    if (NULL == l)    &#123;        perror(&quot;Memory allocation failed&quot;);        return -1;    &#125;    new_node-&gt;data = data;    dlist_node* tail = l;    while (NULL != tail-&gt;next)    &#123;        tail = tail-&gt;next;    &#125;        new_node-&gt;next = NULL;    tail-&gt;next = new_node;    new_node-&gt;prev = tail;&#125;void debug(dlist_head* l)&#123;    const dlist_node* current = l;    while (NULL != current-&gt;next)    &#123;        printf(&quot;current ==&gt; %p, next ==&gt; %p, prev ==&gt; %p\n&quot;,current, current-&gt;next, current-&gt;prev);        current = current-&gt;next;    &#125;    printf(&quot;current ==&gt; %p, next ==&gt; %p, prev ==&gt; %p\n&quot;,current, current-&gt;next, current-&gt;prev);&#125;void print_dlist(const dlist_head* l)&#123;    const dlist_node* current = l;    while (NULL != current-&gt;next)    &#123;        current = current-&gt;next;        printf(&quot;%d ==&gt; &quot;,current-&gt;data);    &#125;    printf(&quot;NULL\n&quot;);&#125;dlist_node* find_node_dlist(dlist_head* l, const datatype_t data)&#123;    dlist_node* current = l;    while (NULL != current-&gt;next)    &#123;        current = current-&gt;next;        if (data == current-&gt;data)        &#123;            return current;        &#125;    &#125;    return NULL;&#125;void delete_dlist_node(dlist_head* l, datatype_t data)&#123;    while (NULL != find_node_dlist(l, data))    &#123;        dlist_node* current = l;        while (NULL != current-&gt;next)        &#123;            current = current-&gt;next;            if (data == current-&gt;data)            &#123;                break;            &#125;        &#125;        current-&gt;prev-&gt;next = current-&gt;next;        if (NULL != current-&gt;next)        &#123;            current-&gt;next-&gt;prev = current-&gt;prev;        &#125;        free(current);        current = NULL;    &#125;&#125;void destroy_dlist(dlist_head* l)&#123;    dlist_node* current = l;    if (NULL == l-&gt;next)    &#123;        free(l);        l = NULL;        return;    &#125;        dlist_node* p = NULL;    while (NULL != current-&gt;next)    &#123;        p = current;        current = current-&gt;next;        free(p);        p = NULL;    &#125;    free(current);    current = NULL;      l = NULL;&#125;

