next = p-&gt;next;            for (size_t i = 1; i &lt; head-&gt;n; i++)            &#123;                q = q-&gt;next;            &#125;            q-&gt;next = p-&gt;next;            free(p);            p = NULL;            head-&gt;n--;            if (head-&gt;n == 0)            &#123;                head-&gt;next = NULL;            &#125;        &#125;            &#125;&#125;void destyroy_sclist(sclist_head* head)&#123;    if (head-&gt;next == NULL)    &#123;        free(head);        head = NULL;        return;    &#125;    sclist_node* p = head-&gt;next;    sclist_node* q = NULL;    for (size_t i = 1; i &lt; head-&gt;n; i++)    &#123;        q = p;        p = p-&gt;next;        free(q);        q = NULL;    &#125;    free(p);    p = NULL;    free(head);    head = NULL;&#125;bool is_empty_sclist(sclist_head* head)&#123;    return head-&gt;next == NULL ? true : false;&#125;uint32_t num_of_node_sclist(sclist_head* head)&#123;    return head-&gt;n;&#125;void print_sclist(const sclist_head* head)&#123;    const sclist_node* current = head-&gt;next;        for (size_t i = 0; i &lt; head-&gt;n; i++)    &#123;        printf(&quot;%d -&gt; &quot;, current-&gt;data);        current = current-&gt;next;    &#125;    printf(&quot;%d\n&quot;, head-&gt;next-&gt;data);&#125;

