            &#123;                break;            &#125;        &#125;        current-&gt;prev-&gt;next = current-&gt;next;        current-&gt;next-&gt;prev = current-&gt;prev;        free(current);        current = NULL;    &#125;&#125;void destroy_dlist(dlist_head* l)&#123;    dlist_node* current = l;    if (l == l-&gt;next)    &#123;        free(l);        l = NULL;        return;    &#125;        dlist_node* p = NULL;    while (l != current-&gt;next)    &#123;        p = current;        current = current-&gt;next;        free(p);        p = NULL;    &#125;    free(current);    current = NULL;      l = NULL;&#125;

