#include &quot;loop_queue.h&quot;loopqueue_t *create_empty_loopqueue()&#123;    loopqueue_t * q = (loopqueue_t*)malloc(sizeof(loopqueue_t));    if (NULL == q)    &#123;        perror(&quot;Failed to allocate memory for loop queue&quot;);        return NULL;    &#125;    q-&gt;front = q-&gt;rear = 0;    return q;&#125;bool is_empty_loopqueue(loopqueue_t *q)&#123;    return q-&gt;front == q-&gt;rear;&#125;bool is_full_loopqueue(loopqueue_t *q)&#123;    return q-&gt;front == (q-&gt;rear + 1) % N;&#125;void enter_loopqueue(loopqueue_t *q, data_t data)&#123;    if (is_full_loopqueue(q))    &#123;        perror(&quot;Failed to enter data into loop queue: queue is full&quot;);        return;    &#125;        q-&gt;buf[q-&gt;rear] = data;    q-&gt;rear = (q-&gt;rear + 1) % N;&#125;data_t delete_loopqueue(loopqueue_t *q)&#123;    if(is_empty_loopqueue(q))    &#123;        perror(&quot;Failed to delete data from loop queue: queue is empty&quot;);        return;    &#125;    data_t data = q-&gt;buf[q-&gt;front];    q-&gt;front = (q-&gt;front + 1) % N;    return data;&#125;

