双端队列双端队列又名double ended queue，简称deque，双端队列没有队列和栈这样的限制级，它允许两端进行入队和出队操作，也就是说元素可以从队头出队和入队，也可以从队尾出队和入队。实现很简单，带尾指针的双链表即可实现，不再赘述。

优先队列二叉堆是优先队列的一种实现方式。二叉堆是一棵完全二叉树，分为大端堆和小端堆，其中每个父节点的值都&gt;=（大端堆）或&lt;=（小端堆）其子节点的值。二叉堆通常用于实现优先队列，支持高效的插入和删除最大元素操作。
下面是大端堆的实现。
#include &lt;stdio.h&gt;#include &lt;stdlib.h&gt;#include &lt;stdbool.h&gt;// 二叉树节点结构体typedef struct Node &#123;    int value;    struct Node* parent;    struct Node* left;    struct Node* right;&#125; Node;// 二叉堆结构体typedef struct &#123;    Node* root;      // 堆的根节点    Node* last_node; // 最后一个节点    int size;        // 堆的大小    Node** queue;    // 用于维护插入位置的队列    int queue_size;  // 队列当前大小    int queue_cap;   // 队列容量&#125; BinaryHeap;// 创建新节点Node* create_node(int value) &#123;    Node* node = (Node*)malloc(sizeof(Node));    node-&gt;value = value;    node-&gt;parent = node-&gt;left = node-&gt;right = NULL;    return node;&#125;// 初始化二叉堆void heap_init(BinaryHeap* heap) &#123;    heap-&gt;root = heap-&gt;last_node = NULL;    heap-&gt;size = 0;    heap-&gt;queue_cap = 8; // 初始队列容量    heap-&gt;queue = (Node**)malloc(sizeof(Node*) * heap-&gt;queue_cap);    heap-&gt;queue_size = 0;&#125;// 扩展队列容量void resize_queue(BinaryHeap* heap) &#123;    heap-&gt;queue_cap *= 2;    heap-&gt;queue = (Node**)realloc(heap-&gt;queue, sizeof(Node*) * heap-&gt;queue_cap);&#125;// 插入节点时的队列操作void enqueue(BinaryHeap* heap, Node* node) &#123;    if (heap-&gt;queue_size &gt;= heap-&gt;queue_cap) resize_queue(heap);    heap-&gt;queue[heap-&gt;queue_size++] = node;&#125;// 取出队列头部节点Node* dequeue(BinaryHeap* heap) &#123;    if (heap-&gt;queue_size == 0) return NULL;    Node* node = heap-&gt;queue[0];    for (int i = 1; i &lt; heap-&gt;queue_size; i++) &#123;        heap-&gt;queue[i-1] = heap-&gt;queue[i];    &#125;    heap-&gt;queue_size--;    return node;&#125;// 上滤操作（保持堆性质）void percolate_up(Node* node) &#123;    while (node-&gt;parent != NULL &amp;&amp; node-&gt;value &gt; node-&gt;parent-&gt;value) &#123;        // 交换父子节点值        int temp = node-&gt;value;        node-&gt;value = node-&gt;parent-&gt;value;        node-&gt;parent-&gt;value = temp;        node = node-&gt;parent;    &#125;&#125;// 插入元素void heap_insert(BinaryHeap* heap, int value) &#123;    Node* new_node = create_node(value);        if (heap-&gt;size == 0) &#123;        heap-&gt;root = heap-&gt;last_node = new_node;        enqueue(heap, new_node);        heap-&gt;size++;        return;    &#125;    Node* parent = heap-&gt;queue[0];    if (parent-&gt;left == NULL) &#123;        parent-&gt;left = new_node;        new_node-&gt;parent = parent;        // 将父节点重新放回队列前端        heap-&gt;queue[0] = parent;        enqueue(heap, new_node);    &#125; else &#123;        parent-&gt;right = new_node;        new_node-&gt;parent = parent;        dequeue(heap); // 父节点处理完毕        enqueue(heap, new_node);    &#125;    heap-&gt;last_node = new_node;    heap-&gt;size++;    percolate_up(new_node);&#125;// 下滤操作（保持堆性质）void percolate_down(Node* node) &#123;    while (true) &#123;        Node* max_child = NULL;        // 比较左右子节点        if (node-&gt;left &amp;&amp; node-&gt;right) &#123;            max_child = (node-&gt;left-&gt;value &gt; node-&gt;right-&gt;value) ? node-&gt;left : node-&gt;right;        &#125; else if (node-&gt;left) &#123;            max_child = node-&gt;left;        &#125; else &#123;            break; // 没有子节点        &#125;        if (max_child-&gt;value &gt; node-&gt;value) &#123;            // 交换节点值            int temp = node-&gt;value;            node-&gt;value = max_child-&gt;value;            max_child-&gt;value = temp;            node = max_child;        &#125; else &#123;            break;        &#125;    &#125;&#125;// 查找最后一个节点（使用二进制路径法）Node* find_last_node(BinaryHeap* heap) &#123;    if (heap-&gt;size == 0) return NULL;        int mask = 1 &lt;&lt; (31 - __builtin_clz(heap-&gt;size)); // 找到最高位    Node* current = heap-&gt;root;        while (mask &gt; 1) &#123;        mask &gt;&gt;= 1;        current = (heap-&gt;size &amp; mask) ? current-&gt;right : current-&gt;left;    &#125;    return current;&#125;// 提取最大值int heap_extract_max(BinaryHeap* heap) &#123;    if (heap-&gt;size == 0) return -1; // 错误码        int max_val = heap-&gt;root-&gt;value;    if (heap-&gt;size == 1) &#123;        free(heap-&gt;root);        heap-&gt;root = heap-&gt;last_node = NULL;        heap-&gt;size = 0;        return max_val;    &#125;    // 将最后一个节点的值移到根节点    heap-&gt;root-&gt;value = heap-&gt;last_node-&gt;value;        // 删除最后一个节点    Node* parent = heap-&gt;last_node-&gt;parent;    if (parent-&gt;right == heap-&gt;last_node) &#123;        free(parent-&gt;right);        parent-&gt;right = NULL;    &#125; else &#123;        free(parent-&gt;left);        parent-&gt;left = NULL;    &#125;        heap-&gt;size--;    heap-&gt;last_node = find_last_node(heap);    percolate_down(heap-&gt;root);    return max_val;&#125;// 清理堆内存void heap_clean(BinaryHeap* heap) &#123;    // 实现层次遍历清理内存（此处省略具体实现）    free(heap-&gt;queue);&#125;/*************** 测试用例 ***************/int main() &#123;    BinaryHeap heap;    heap_init(&amp;heap);    // 插入测试    heap_insert(&amp;heap, 5);    heap_insert(&amp;heap, 8);    heap_insert(&amp;heap, 3);    heap_insert(&amp;heap, 11);    heap_insert(&amp;heap, 10);    heap_insert(&amp;heap, 18);    // 提取最大值测试    printf(&quot;Max: %d\n&quot;, heap_extract_max(&amp;heap)); // 18    printf(&quot;Max: %d\n&quot;, heap_extract_max(&amp;heap)); // 11    printf(&quot;Max: %d\n&quot;, heap_extract_max(&amp;heap)); // 10    printf(&quot;Max: %d\n&quot;, heap_extract_max(&amp;heap)); // 8    printf(&quot;Max: %d\n&quot;, heap_extract_max(&amp;heap)); // 5        heap_clean(&amp;heap);    return 0;&#125;

