二叉查找树二叉查找树的定义（Binary Search Tree）：

该树是一颗二叉树。
如果左子树不为空，则左子树上所有节点的值均小于根节点的值。
如果右子树不为空，则右子树上所有节点的值均大于根节点的值。
左、右子树也都是二叉查找树。

二叉查找树最坏情况就是一个链表。
#include &lt;stdio.h&gt;#include &lt;stdlib.h&gt;// 定义二叉查找树的节点结构struct TreeNode &#123;    int data;    struct TreeNode *left;    struct TreeNode *right;&#125;;// 创建新节点struct TreeNode* createNode(int value) &#123;    struct TreeNode* newNode = (struct TreeNode*)malloc(sizeof(struct TreeNode));    newNode-&gt;data = value;    newNode-&gt;left = NULL;    newNode-&gt;right = NULL;    return newNode;&#125;// 插入节点struct TreeNode* insert(struct TreeNode* root, int value) &#123;    // 如果树为空，创建新节点并返回    if (root == NULL) &#123;        return createNode(value);    &#125;    // 如果值小于当前节点的值，插入到左子树    if (value &lt; root-&gt;data) &#123;        root-&gt;left = insert(root-&gt;left, value);    &#125;    // 如果值大于当前节点的值，插入到右子树    else if (value &gt; root-&gt;data) &#123;        root-&gt;right = insert(root-&gt;right, value);    &#125;    // 返回当前节点    return root;&#125;// 查找节点struct TreeNode* search(struct TreeNode* root, int value) &#123;    // 如果树为空或找到目标值    if (root == NULL || root-&gt;data == value) &#123;        return root;    &#125;    // 如果值小于当前节点的值，查找左子树    if (value &lt; root-&gt;data) &#123;        return search(root-&gt;left, value);    &#125;    // 如果值大于当前节点的值，查找右子树    else &#123;        return search(root-&gt;right, value);    &#125;&#125;// 中序遍历（用于打印树的内容）void inorderTraversal(struct TreeNode* root) &#123;    if (root != NULL) &#123;        inorderTraversal(root-&gt;left);        printf(&quot;%d &quot;, root-&gt;data);        inorderTraversal(root-&gt;right);    &#125;&#125;// 测试二叉查找树的创建和查找int main() &#123;    struct TreeNode* root = NULL;    // 插入节点    root = insert(root, 50);    insert(root, 30);    insert(root, 20);    insert(root, 40);    insert(root, 70);    insert(root, 60);    insert(root, 80);    // 中序遍历打印树的内容    printf(&quot;中序遍历结果: \n&quot;);    inorderTraversal(root);    printf(&quot;\n&quot;);    // 查找节点    int searchValue = 40;    struct TreeNode* result = search(root, searchValue);    if (result != NULL) &#123;        printf(&quot;找到节点: %d\n&quot;, result-&gt;data);    &#125; else &#123;        printf(&quot;未找到节点: %d\n&quot;, searchValue);    &#125;    return 0;&#125;

