node = NULL;    s-&gt;n--;    return data;&#125;data_t get_top_data(linkstack_t *s)&#123;    if (is_empty_linkstack(s))    &#123;        perror(&quot;Stack is empty&quot;);         return -1;    &#125;    return s-&gt;top-&gt;data;&#125;int get_num_of_linkstack(linkstack_t *s)&#123;    return s-&gt;n;&#125;//main.c#include &quot;link_queue.h&quot;#include &quot;link_stack.h&quot;#define N 27bool is_orginal_queue(linkqueue_t * lq) &#123;	qlinknode_t* p;	if (NULL == lq) &#123;		printf(&quot;lq is NULL\n&quot;);		return -1;	&#125;	p = lq-&gt;front;	while (p &amp;&amp; p-&gt;next)    &#123;		if (p-&gt;data &lt; p-&gt;next-&gt;data)         &#123;			p = p-&gt;next;		&#125;        else         &#123;			return false;		&#125;	&#125;	return true;&#125;int main(int argc, char const *argv[])&#123;    linkqueue_t* ball_queue = create_empty_linkqueue();    linkstack_t* min_stack = create_empty_linkstack();    linkstack_t* min5_stack = create_empty_linkstack();    linkstack_t* hour_stack = create_empty_linkstack();    int min = 0;    int ball = 0;    int half_day = 0;    for (size_t i = 0; i &lt; N; i++)    &#123;        enqueue_linkqueue(ball_queue, i);    &#125;    while (true)    &#123;        ball = dequeue_linkqueue(ball_queue);        min++;        if(get_num_of_linkstack(min_stack) &lt; 4)        &#123;            push_linkstack(min_stack, ball);            continue;        &#125;        while(!is_empty_linkstack(min_stack))        &#123;            enqueue_linkqueue(ball_queue,pop_linkstack(min_stack));        &#125;        if(get_num_of_linkstack(min5_stack) &lt; 11)        &#123;            push_linkstack(min5_stack, ball);            continue;        &#125;        while(!is_empty_linkstack(min5_stack))        &#123;            enqueue_linkqueue(ball_queue,pop_linkstack(min5_stack));        &#125;        if(get_num_of_linkstack(hour_stack) &lt; 11)        &#123;            push_linkstack(hour_stack, ball);            continue;        &#125;        while(!is_empty_linkstack(hour_stack))        &#123;            enqueue_linkqueue(ball_queue,pop_linkstack(hour_stack));        &#125;        // 满时间最后一球入队        enqueue_linkqueue(ball_queue, ball);        half_day++;        if(is_orginal_queue(ball_queue))        &#123;            break;        &#125;      &#125;    // 23 33120    printf(&quot;days ==&gt; %d\nmin ==&gt;%d\n&quot;, half_day / 2, min);        return 0;&#125;

表达式求值中缀表达式求值（ &#39;+&#39; , &#39;-&#39; , &#39;*&#39; , &#39;/&#39; , &#39;(&#39; , &#39;)&#39; ）（不转逆波兰式）。
#include &lt;bits/stdc++.h&gt;using namespace std;// 判断运算符的优先级int precedence(char op) &#123;    switch (op)    &#123;        case &#x27;+&#x27;:        case &#x27;-&#x27;:            return 1;            break;        case &#x27;*&#x27;:        case &#x27;/&#x27;:            return 2;            break;        default:            return 0;            break;    &#125;&#125;int calculate(int a, int b, char op) &#123;    switch (op)     &#123;        case &#x27;+&#x27;:             return a + b;            break;        case &#x27;-&#x27;:             return a - b;            break;        case &#x27;*&#x27;:             return a * b;            break;        case &#x27;/&#x27;:             return a / b;            break;        default:             return 0;    &#125;&#125;// 处理栈中的操作符并计算void process_stack(stack&lt;int&gt;&amp; operand_stack, stack&lt;char&gt;&amp; operator_stack) &#123;    int b = operand_stack.top(); operand_stack.pop();    int a = operand_stack.top(); operand_stack.pop();    char op = operator_stack.top(); operator_stack.pop();    operand_stack.push(calculate(a, b, op));&#125;// 计算表达式的值int evaluate_expression(const string&amp; expr) &#123;    stack&lt;int&gt; operand_stack;    stack&lt;char&gt; operator_stack;    for (size_t i = 0; i &lt; expr.length(); ++i)     &#123;        char ch = expr[i];        if (ch == &#x27; &#x27;)         &#123;            continue;        &#125;        if (isdigit(ch))         &#123;            int num = 0;            while (i &lt; expr.length() &amp;&amp; isdigit(expr[i]))             &#123;                num = num * 10 + (expr[i] - &#x27;0&#x27;);                i++;            &#125;            i--; // 回退多读取的字符            operand_stack.push(num);        &#125;        else if (ch == &#x27;(&#x27;)         &#123;            operator_stack.push(ch);        &#125;        else if (ch == &#x27;)&#x27;)         &#123;            while (!operator_stack.empty() &amp;&amp; operator_stack.top() != &#x27;(&#x27;)             &#123;                process_stack(operand_stack, operator_stack);            &#125;            if (!operator_stack.empty() &amp;&amp; operator_stack.top() == &#x27;(&#x27;)             &#123;                operator_stack.pop(); // 弹出左括号            &#125;        &#125;        else if (ch == &#x27;+&#x27; || ch == &#x27;-&#x27; || ch == &#x27;*&#x27; || ch == &#x27;/&#x27;)         &#123;            while (!operator_stack.empty() &amp;&amp;                   precedence(operator_stack.top()) &gt;= precedence(ch) &amp;&amp;                   operator_stack.top() != &#x27;(&#x27;)             &#123;                process_stack(operand_stack, operator_stack);            &#125;            operator_stack.push(ch);        &#125;        else        &#123;            puts(&quot;Invalid character in expression&quot;);            exit(1);        &#125;    &#125;    // 最后处理剩余的运算符    while (!operator_stack.empty())     &#123;        process_stack(operand_stack, operator_stack);    &#125;    return operand_stack.top();  // 返回最终计算结果&#125;int main() &#123;    string expr;    puts(&quot;Enter an expression:&quot;);    getline(cin, expr);    int result = evaluate_expression(expr);    printf(&quot;Result: %d\n&quot;, result);    return 0;&#125;

